    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        if (file.size > 5 * 1024 * 1024) {
            setApiError('File size cannot exceed 5MB.');
            return;
        }

        try {
            const reader = new FileReader();
            reader.onerror = () => {
                setApiError("Sorry, I couldn't read that file. Please try another one.");
                setUploadedFile(null);
            };

            if (file.type.startsWith('image/')) {
                reader.onload = (event) => {
                    const result = event.target?.result;
                    if (typeof result === 'string' && result.startsWith('data:image/')) {
                        setUploadedFile({ name: file.name, content: result, type: 'image', mimeType: file.type });
                        setApiError(null);
                    } else {
                        setApiError("The selected image appears to be invalid or corrupted. Please try a different file.");
                        setUploadedFile(null);
                    }
                };
                reader.readAsDataURL(file);
            } else {
                reader.onload = (event) => {
                    const result = event.target?.result;
                    if (typeof result === 'string') {
                        setUploadedFile({ name: file.name, content: result, type: 'text' });
                        setApiError(null);
                    } else {
                        setApiError("Failed to read the text file content.");
                        setUploadedFile(null);
                    }
                };
                reader.readAsText(file);
            }
        } catch (error) {
            console.error("Error reading file:", error);
            setApiError("There was an issue processing your file.");
            setUploadedFile(null);
        }

        if (e.target) e.target.value = ''; // Reset file input
    };

    const downloadFile = (url: string, filename: string) => {
        const a = document.createElement('a'); a.href = url; a.download = filename;
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const handleDownloadImage = (msgId: string, imageUrl: string, filename: string) => {
        setDownloadingFile(msgId);
        if (imageUrl.startsWith('data:')) {
             const mimeType = imageUrl.match(/data:([^;]+);/)?.[1] || 'image/jpeg';
             const base64 = imageUrl.split(',')[1];
             const byteCharacters = atob(base64);
             const byteNumbers = new Array(byteCharacters.length);
             for (let i = 0; i < byteCharacters.length; i++) byteNumbers[i] = byteCharacters.charCodeAt(i);
             const byteArray = new Uint8Array(byteNumbers);
             const blob = new Blob([byteArray], { type: mimeType });
             const url = URL.createObjectURL(blob);
             downloadFile(url, filename);
             setDownloadingFile(null);
             return;
        }

        fetch(imageUrl)
            .then(response => response.blob())
            .then(blob => {
                const url = URL.createObjectURL(blob);
                downloadFile(url, filename);
            })
            .catch(err => {
                console.error("Image download failed", err);
                window.open(imageUrl, '_blank');
            })
            .finally(() => {
                setDownloadingFile(null);
            });
    };

    const handleDownloadPdf = (msgId: string, text: string, filename: string) => {
        setDownloadingFile(msgId);

        const doc = new jsPDF({
            orientation: 'portrait',
            unit: 'pt',
            format: 'a4'
        });

        const pageWidth = doc.internal.pageSize.getWidth();
        const pageHeight = doc.internal.pageSize.getHeight();
        const margin = 40;
        const maxLineWidth = pageWidth - (margin * 2);

        let pageNumber = 1;
        const addPageWithHeader = () => {
             doc.addPage();
             pageNumber++;
             return margin + 20;
        }

        let y = margin;
        doc.setFillColor(14, 165, 233);
        doc.rect(0, 0, pageWidth, 5, 'F');
        doc.setFont("helvetica", "bold");
        doc.setFontSize(22);
        doc.setTextColor(51, 65, 85);
        doc.text("Nova Intelligence", margin, y + 30);
        y += 45;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        doc.setTextColor(100, 116, 139);
        const dateStr = new Date().toLocaleDateString();
        doc.text(`Generated by CollabSea • ${dateStr}`, margin, y);
        y += 20;
        doc.setDrawColor(226, 232, 240);
        doc.line(margin, y, pageWidth - margin, y);
        y += 35;
        doc.setTextColor(30, 41, 59);

        let cleanText = text.replace(/^(Sure|Here|I have|Certainly).*?(\n\n|\n)/i, '');
        cleanText = cleanText.replace(/\*\*(.*?)\*\*/g, '$1').replace(/\*(.*?)\*/g, '$1');

        const lines = cleanText.split('\n');

        lines.forEach((line) => {
            const trimmed = line.trim();
            if (!trimmed) {
                y += 10;
                return;
            }

            if (trimmed === '---') {
                y = addPageWithHeader();
                return;
            }

            if (trimmed.startsWith('# ')) {
                doc.setFont("helvetica", "bold");
                doc.setFontSize(18);
                const title = trimmed.replace('# ', '');
                const titleLines = doc.splitTextToSize(title, maxLineWidth);
                doc.text(titleLines, margin, y);
                y += (titleLines.length * 22) + 10;
                return;
            }

            if (trimmed.startsWith('## ')) {
                doc.setFont("helvetica", "bold");
                doc.setFontSize(14);
                const subtitle = trimmed.replace('## ', '');
                const subLines = doc.splitTextToSize(subtitle, maxLineWidth);
                doc.text(subLines, margin, y);
                y += (subLines.length * 18) + 8;
                return;
            }

            if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
                doc.setFont("helvetica", "normal");
                doc.setFontSize(11);
                const bulletText = trimmed.substring(2);
                const bulletLines = doc.splitTextToSize(bulletText, maxLineWidth - 15);

                doc.text('•', margin, y);
                doc.text(bulletLines, margin + 15, y);
                y += (bulletLines.length * 14) + 5;

                 if (y > pageHeight - margin) {
                    y = addPageWithHeader();
                }
                return;
            }

            doc.setFont("helvetica", "normal");
            doc.setFontSize(11);
            const textLines = doc.splitTextToSize(trimmed, maxLineWidth);

            if (y + (textLines.length * 14) > pageHeight - margin) {
                y = addPageWithHeader();
            }

            doc.text(textLines, margin, y);
            y += (textLines.length * 14) + 10;
        });

        const pageCount = doc.internal.pages.length - 1;
        for (let i = 1; i <= pageCount; i++) {
            doc.setPage(i);
            doc.setFontSize(9);
            doc.setTextColor(148, 163, 184);
            doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 20, { align: 'right' });
        }

        doc.save(filename);
        setDownloadingFile(null);
    };

    const handleDownloadZip = async (text: string) => {
        setGenerationMessage("Compressing project files...");
        try {
            const zip = new JSZip();
            const fileRegex = /@@FILE:\s*([^\s@]+)@@[\s\S]*?```[\w-]*\s*([\s\S]*?)```/g;
            let match;
            let count = 0;

            while ((match = fileRegex.exec(text)) !== null) {
                count++;
                let filePath = match[1].trim();
                filePath = filePath.replace(/['"`]/g, ''); 
                let fileContent = match[2];
                fileContent = fileContent.replace(/^\n+/, '').replace(/\n+$/, '');
                zip.file(filePath, fileContent);
            }

            if (count === 0) {
                alert("Could not parse project files. The output format might have been incorrect. Please try generating again.");
                setGenerationMessage(null);
                return;
            }

            const content = await zip.generateAsync({ type: "blob" });
            const url = URL.createObjectURL(content);
            const a = document.createElement("a");
            a.href = url;
            a.download = "nova-app-project.zip";
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        } catch (e) {
            console.error("Zip error", e);
            alert("Failed to create zip file.");
        } finally {
            setGenerationMessage(null);
        }
    };

    const executeSkill = async (
        prompt: string,
        file: { name: string; content: string; type: 'text' | 'image'; mimeType?: string } | null,
        skill: ActiveSkill,
        userEmotion: EmotionResult | null = null
    ) => {
        if (!userProfile) return;

        setLoading(true);
        setApiError(null);
        if (skill === 'imageGen') setGenerationMessage("Crafting your image...");
        else if (skill === 'videoGen') setGenerationMessage("Producing your video with Gemini Veo...");
        else if (skill === 'docGen') setGenerationMessage("Drafting that up for you...");
        else if (skill === 'trends') setGenerationMessage("Let's see what's trending...");
        else if (skill === 'appGen') setGenerationMessage("Building your application... This may take a few moments.");
        else setGenerationMessage(null);

        const historyRef = collection(db, 'users', userProfile.uid, 'nova_history');

        try {
            // Ensure fresh API Key is used if updated via dialog
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            let modelResponse: Omit<NovaMessage, 'id'> | null = null;

            if (skill === 'imageGen') {
                try {
                    const response = await ai.models.generateImages({
                        model: 'imagen-4.0-generate-001',
                        prompt: prompt,
                        config: {
                            numberOfImages: 1,
                            outputMimeType: 'image/jpeg',
                            aspectRatio: '1:1',
                        },
                    });

                    const base64Image = response.generatedImages?.[0]?.image?.imageBytes;

                    if (base64Image) {
                        const byteCharacters = atob(base64Image);
                        const byteNumbers = new Array(byteCharacters.length);
                        for (let i = 0; i < byteCharacters.length; i++) {
                            byteNumbers[i] = byteCharacters.charCodeAt(i);
                        }
                        const byteArray = new Uint8Array(byteNumbers);
                        const blob = new Blob([byteArray], { type: 'image/jpeg' });

                        const { url } = await uploadMedia(blob, userProfile.uid, 'post');

                        modelResponse = {
                            role: 'model',
                            text: `Here is the image I generated for "${prompt}":`,
                            imageUrl: url,
                            fromSkill: 'imageGen'
                        };
                    } else {
                        modelResponse = { 
                            role: 'model', 
                            text: "I'm sorry, I couldn't generate an image for that prompt.", 
                            fromSkill: 'imageGen' 
                        };
                    }
                } catch (error: any) {
                    console.error("Image generation failed:", error);
                    const errStr = error.message || String(error);
                    modelResponse = { 
                        role: 'model', 
                        text: `I couldn't generate the image. ${errStr.includes("403") ? "Access denied to image model." : "There was a technical issue."}`, 
                        fromSkill: 'imageGen' 
                    };
                }
            } else if (skill === 'videoGen') {
                // Video Generation using Gemini Veo
                try {
                     // Check if user has selected a paid API key for Veo
                    const hasKey = await (window as any).aistudio?.hasSelectedApiKey();
                    if (!hasKey) {
                        modelResponse = {
                            role: 'model',
                            text: "To generate cinematic videos with Gemini Veo, you need to connect a paid API key.",
                            fromSkill: 'videoGen',
                            isApiKeyRequest: true
                        };
                        // We break early to ask for the key
                        if (modelResponse) {
                             await addDoc(historyRef, { ...modelResponse, timestamp: serverTimestamp() });
                        }
                        setLoading(false);
                        setGenerationMessage(null);
                        return;
                    }

                    let operation = await ai.models.generateVideos({
                      model: 'veo-3.1-generate-preview',
                      prompt: prompt,
                      config: {
                        numberOfVideos: 1,
                        resolution: '720p',
                        aspectRatio: '16:9'
                      }
                    });

                    // Poll for completion
                    while (!operation.done) {
                      await new Promise(resolve => setTimeout(resolve, 5000));
                      operation = await ai.operations.getVideosOperation({operation: operation});
                    }

                    const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;

                    if (videoUri) {
                        // The video URI requires an API key appended to download
                        const fetchUrl = `${videoUri}&key=${process.env.API_KEY}`;
                        const response = await fetch(fetchUrl);

                        if (!response.ok) throw new Error("Failed to download generated video.");

                        const blob = await response.blob();
                        const { url } = await uploadMedia(blob, userProfile.uid, 'audio'); // Reuse audio/video folder mapping

                        modelResponse = {
                            role: 'model',
                            text: `Here is the video I generated for "${prompt}" using Gemini Veo:`,
                            videoUrl: url,
                            fromSkill: 'videoGen'
                        };
                    } else {
                        throw new Error("No video URI returned.");
                    }

                } catch (error: any) {
                    console.error("Veo Video generation failed:", error);
                    let errorMsg = `I'm sorry, I encountered an issue generating your video. (${error.message})`;
                    let isKeyError = false;

                    if (error.message.includes("403") || error.message.includes("PERMISSION_DENIED") || error.message.includes("Requested entity was not found")) {
                         errorMsg = "Access to the Gemini Veo model is restricted. Please ensure you have selected a valid API key with billing enabled.";
                         isKeyError = true;
                    }
                    modelResponse = {
                        role: 'model',
                        text: errorMsg,
                        fromSkill: 'videoGen',
                        isApiKeyRequest: isKeyError
                    }
                }

            } else {
                let systemInstruction = getSystemInstruction();
                if (skill === 'appGen') systemInstruction = getAppGenSystemInstruction();
                if (skill === 'docGen') systemInstruction = getDocGenSystemInstruction();

                let promptText = prompt;
                if (userEmotion) {
                    promptText = `[User's detected emotion: ${userEmotion.label} (Confidence: ${userEmotion.score.toFixed(2)})]\n\n${promptText}`;
                }

                if (skill === 'docGen') {
                    promptText += "\n\n(IMPORTANT: Generate ONLY the document content. Do not include any chat, greetings, or introductory text. Start directly with the # Title.)";
                }

                const currentHistory = messagesRef.current;

                const historyContents: Content[] = currentHistory.map(msg => {
                    const parts: Part[] = [];
                    if (msg.text) parts.push({ text: msg.text });
                    if (msg.role === 'user' && msg.uploadedImageUrl) {
                        const mimeType = msg.uploadedImageUrl.match(/data:([^;]+);/)?.[1] || 'image/jpeg';
                        const data = msg.uploadedImageUrl.split(',')[1];
                        parts.push({ inlineData: { mimeType, data } });
                    }
                    return { role: msg.role, parts };
                }).filter(c => c.parts.length > 0);

                const userParts: Part[] = [{ text: promptText }];
                if (file?.type === 'image') {
                    const mimeType = file.mimeType || 'image/jpeg';
                    const data = file.content.split(',')[1];
                    userParts.push({ inlineData: { mimeType, data } });
                }

                const allContents = [...historyContents, { role: 'user', parts: userParts }];

                let modelToUse = (skill === 'appGen' || skill === 'docGen' || skill === 'workflow') 
                    ? 'gemini-3-pro-preview' 
                    : 'gemini-2.5-flash';

                const config: any = { systemInstruction };
                if (skill === 'trends') config.tools = [{ googleSearch: {} }];

                if (skill === 'appGen') {
                    config.temperature = 0.2;
                }

                try {
                    const apiResponse = await ai.models.generateContent({ model: modelToUse, contents: allContents, config });
                    const responseText = apiResponse.text;

                    if (!responseText) {
                        throw new Error("Received empty response from AI.");
                    }

                    modelResponse = { role: 'model', text: responseText, fromSkill: skill };

                    if (skill === 'trends') {
                        modelResponse.sources = apiResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => c.web).filter(Boolean) || [];
                    }
                    if (skill === 'docGen') {
                        modelResponse.pdfContent = responseText;
                        modelResponse.text = `Here is the document draft I've prepared for you on: "${prompt}"`;
                    }
                } catch (error: any) {
                    const errStr = error.message || String(error);
                    if ((errStr.includes("403") || errStr.includes("PERMISSION_DENIED") || errStr.includes("404")) && modelToUse !== 'gemini-2.5-flash') {
                        console.warn(`Model ${modelToUse} failed with permission error. Falling back to gemini-2.5-flash.`);
                        const fallbackResponse = await ai.models.generateContent({ 
                            model: 'gemini-2.5-flash', 
                            contents: allContents, 
                            config 
                        });
                        const fallbackText = fallbackResponse.text;
                        if (!fallbackText) throw new Error("Empty response from fallback model.");
                        modelResponse = { role: 'model', text: fallbackText, fromSkill: skill };
                        if (skill === 'docGen') {
                            modelResponse.pdfContent = fallbackText;
                            modelResponse.text = `Here is the document draft (Standard Mode) for: "${prompt}"`;
                        }
                    } else {
                        throw error;
                    }
                }
            }

            if (modelResponse) {
                await addDoc(historyRef, { ...modelResponse, timestamp: serverTimestamp() });
            }
        } catch (error: any) {
            console.error("Error in NovaScreen:", error);

            let userFriendlyError = "My apologies, I'm having trouble connecting. Let's try that again in a moment.";
            const errorString = error.message || String(error) || JSON.stringify(error);
            if (errorString.includes("429") || errorString.includes("quota") || errorString.includes("RESOURCE_EXHAUSTED")) {
                userFriendlyError = "I'm receiving too many messages at once. Please give me a moment to catch up.";
            } else if (errorString.includes("Empty response")) {
                userFriendlyError = "I couldn't generate a response for that. Please try rephrasing.";
            } else if (errorString.includes("403") || errorString.includes("PERMISSION_DENIED")) {
                userFriendlyError = "I'm unable to access the requested AI model with your current plan. Please try a simpler request.";
            }

            setApiError(userFriendlyError);
            await addDoc(historyRef, { role: 'model', text: userFriendlyError, timestamp: serverTimestamp() });
        } finally {
            setLoading(false);
            setGenerationMessage(null);
        }
    };

