export type AnimationStyle = 'neon-pulse' | 'kinetic-slide' | 'matrix-rain' | 'fade-zoom';

export interface VideoConfig {
    text: string;
    secondaryText?: string;
    duration: number; // in seconds
    style: AnimationStyle;
    backgroundColor: string; // hex
    accentColor: string; // hex
    fps: number;
}

export interface VideoGenerationResponse {
    success: boolean;
    videoUrl?: string;
    error?: string;
    metadata?: {
        duration: number;
        size: number;
        format: string;
    };
}

import { VideoConfig } from './types';

export class VideoRenderer {
    private canvas: HTMLCanvasElement;
    private ctx: CanvasRenderingContext2D;
    private width: number = 1080;
    private height: number = 1920; // 9:16 aspect ratio

    constructor() {
        this.canvas = document.createElement('canvas');
        this.canvas.width = this.width;
        this.canvas.height = this.height;
        const context = this.canvas.getContext('2d');
        if (!context) throw new Error("Could not get 2D context");
        this.ctx = context;
    }

    private drawBackground(color: string) {
        this.ctx.fillStyle = color;
        this.ctx.fillRect(0, 0, this.width, this.height);
    }

    private drawNeonPulse(config: VideoConfig, progress: number) {
        const { text, accentColor } = config;
        this.drawBackground(config.backgroundColor);

        const scale = 1 + Math.sin(progress * Math.PI * 4) * 0.05;
        const alpha = 0.5 + Math.sin(progress * Math.PI * 2) * 0.5;

        this.ctx.save();
        this.ctx.translate(this.width / 2, this.height / 2);
        this.ctx.scale(scale, scale);

        // Glow effect
        this.ctx.shadowBlur = 40 + Math.sin(progress * Math.PI * 4) * 20;
        this.ctx.shadowColor = accentColor;

        this.ctx.fillStyle = "#ffffff";
        this.ctx.font = "bold 80px Inter, sans-serif";
        this.ctx.textAlign = "center";
        this.ctx.textBaseline = "middle";

        // Wrap text logic would go here, simple version for now
        const words = text.split(' ');
        let line = '';
        let y = 0;

        // Simple multi-line handling
        if (text.length > 20) {
             const mid = Math.floor(words.length / 2);
             const line1 = words.slice(0, mid).join(' ');
             const line2 = words.slice(mid).join(' ');
             this.ctx.fillText(line1, 0, -50);
             this.ctx.fillText(line2, 0, 50);
        } else {
             this.ctx.fillText(text, 0, 0);
        }

        // Animated Circle
        this.ctx.strokeStyle = accentColor;
        this.ctx.lineWidth = 10;
        this.ctx.beginPath();
        this.ctx.arc(0, 0, 400 + Math.sin(progress * Math.PI * 2) * 20, 0, Math.PI * 2);
        this.ctx.stroke();

        this.ctx.restore();
    }

    private drawKineticSlide(config: VideoConfig, progress: number) {
        const { text, accentColor, backgroundColor } = config;
        this.drawBackground(backgroundColor);

        const slideOffset = (progress * this.width * 2) % (this.width + 500) - 250;

        this.ctx.save();
        this.ctx.translate(this.width / 2, this.height / 2);
        this.ctx.rotate(-Math.PI / 6); // Tilt

        this.ctx.fillStyle = accentColor;
        this.ctx.font = "bold 120px Inter, sans-serif";
        this.ctx.textAlign = "center";

        // Repeated text pattern
        for(let i = -5; i <= 5; i++) {
            const dir = i % 2 === 0 ? 1 : -1;
            const xPos = dir * (progress * 1000) % 1000 - 500;

            this.ctx.globalAlpha = 1 - (Math.abs(i) * 0.15);
            this.ctx.fillText(text.toUpperCase(), xPos, i * 140);
        }

        this.ctx.restore();
    }

    private drawMatrixRain(config: VideoConfig, progress: number) {
        // Simplified Matrix effect
        this.ctx.fillStyle = 'rgba(0, 0, 0, 0.1)'; // Fade effect
        this.ctx.fillRect(0, 0, this.width, this.height);

        this.ctx.fillStyle = config.accentColor;
        this.ctx.font = "20px monospace";

        const columns = Math.floor(this.width / 20);
        // We use a pseudo-random determinstic pattern based on progress
        for (let i = 0; i < columns; i++) {
            const y = (Math.tan(i * 135.5) * 1000 + progress * 2000) % this.height;
            const char = String.fromCharCode(0x30A0 + Math.random() * 96);
            this.ctx.fillText(char, i * 20, y);
        }

        // Overlay Text
        this.ctx.save();
        this.ctx.fillStyle = "#ffffff";
        this.ctx.shadowColor = "#000000";
        this.ctx.shadowBlur = 10;
        this.ctx.font = "bold 70px Inter, sans-serif";
        this.ctx.textAlign = "center";
        this.ctx.textBaseline = "middle";
        this.ctx.fillText(config.text, this.width/2, this.height/2);
        this.ctx.restore();
    }

    public async generate(config: VideoConfig): Promise<Blob> {
        const stream = this.canvas.captureStream(config.fps);
        const recorder = new MediaRecorder(stream, {
            mimeType: 'video/webm;codecs=vp9'
        });

        const chunks: BlobPart[] = [];
        recorder.ondataavailable = (e) => {
            if (e.data.size > 0) chunks.push(e.data);
        };

        return new Promise((resolve, reject) => {
            recorder.onstop = () => {
                const blob = new Blob(chunks, { type: 'video/webm' });
                resolve(blob);
            };

            recorder.onerror = (e) => reject(e);

            recorder.start();

            let currentFrame = 0;
            const totalFrames = config.duration * config.fps;

            const renderLoop = () => {
                if (currentFrame >= totalFrames) {
                    recorder.stop();
                    return;
                }

                const progress = currentFrame / totalFrames;

                switch (config.style) {
                    case 'neon-pulse':
                        this.drawNeonPulse(config, progress);
                        break;
                    case 'kinetic-slide':
                        this.drawKineticSlide(config, progress);
                        break;
                    case 'matrix-rain':
                        this.drawMatrixRain(config, progress);
                        break;
                    default:
                        this.drawNeonPulse(config, progress);
                }

                currentFrame++;
                // Use setTimeout to allow the event loop to process MediaRecorder events
                // 0ms delay basically implies "next tick" but gives breathing room
                setTimeout(renderLoop, 1000 / config.fps); 
            };

            renderLoop();
        });
    }
}

import { VideoConfig, VideoGenerationResponse } from './types';
import { VideoRenderer } from './VideoRenderer';

/**
 * Simulates POST /nova/custom_video
 * This runs client-side but mimics an async API call structure.
 */
export async function postCustomVideo(config: VideoConfig): Promise<VideoGenerationResponse> {
    try {
        const renderer = new VideoRenderer();
        const videoBlob = await renderer.generate(config);
        const videoUrl = URL.createObjectURL(videoBlob);

        return {
            success: true,
            videoUrl: videoUrl,
            metadata: {
                duration: config.duration,
                size: videoBlob.size,
                format: 'video/webm'
            }
        };
    } catch (error: any) {
        console.error("Custom Video Gen Error:", error);
        return {
            success: false,
            error: error.message || "Unknown error during video generation"
        };
    }
}

