            if (file.type.startsWith('image/')) {
                reader.onload = (event) => {
                    const result = event.target?.result;
                    if (typeof result === 'string' && result.startsWith('data:image/')) {
                        setUploadedFile({ name: file.name, content: result, type: 'image', mimeType: file.type });
                        setApiError(null);
                    }
