export default NovaScreen;

export type AnimationStyle = 'neon-pulse' | 'kinetic-slide' | 'matrix-rain' | 'cyber-grid' | 'neural-net';

export interface VideoConfig {
    text: string;
    secondaryText?: string;
    duration: number; // in seconds
    style: AnimationStyle;
    backgroundColor: string; // hex
    accentColor: string; // hex
    fps: number;
}

export interface VideoGenerationResponse {
    success: boolean;
    videoUrl?: string;
    error?: string;
    metadata?: {
        duration: number;
        size: number;
        format: string;
    };
}

import { VideoConfig, AnimationStyle } from './types';

export class VideoRenderer {
    private canvas: HTMLCanvasElement;
    private ctx: CanvasRenderingContext2D;
    private width: number = 1080;
    private height: number = 1920; // 9:16 aspect ratio

    constructor() {
        this.canvas = document.createElement('canvas');
        this.canvas.width = this.width;
        this.canvas.height = this.height;
        const context = this.canvas.getContext('2d');
        if (!context) throw new Error("Could not get 2D context");
        this.ctx = context;
    }

    /**
     * Renders a single frame to the provided context.
     * Static to allow usage in both the MediaRecorder loop and the UI Live Preview.
     */
    public static drawFrame(
        ctx: CanvasRenderingContext2D, 
        config: VideoConfig, 
        progress: number, 
        width: number, 
        height: number
    ) {
        // Clear background
        ctx.fillStyle = config.backgroundColor;
        ctx.fillRect(0, 0, width, height);

        switch (config.style) {
            case 'neon-pulse':
                this.drawNeonPulse(ctx, config, progress, width, height);
                break;
            case 'kinetic-slide':
                this.drawKineticSlide(ctx, config, progress, width, height);
                break;
            case 'matrix-rain':
                this.drawMatrixRain(ctx, config, progress, width, height);
                break;
            case 'cyber-grid':
                this.drawCyberGrid(ctx, config, progress, width, height);
                break;
            case 'neural-net':
                this.drawNeuralNet(ctx, config, progress, width, height);
                break;
            default:
                this.drawNeonPulse(ctx, config, progress, width, height);
        }
    }

    private static drawNeonPulse(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { text, accentColor } = config;

        const scale = 1 + Math.sin(progress * Math.PI * 4) * 0.05;

        ctx.save();
        ctx.translate(width / 2, height / 2);
        ctx.scale(scale, scale);

        // Glow effect
        ctx.shadowBlur = 40 + Math.sin(progress * Math.PI * 4) * 20;
        ctx.shadowColor = accentColor;

        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`; // Responsive font
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";

        // Text Wrap
        const words = text.split(' ');
        if (text.length > 20) {
             const mid = Math.floor(words.length / 2);
             const line1 = words.slice(0, mid).join(' ');
             const line2 = words.slice(mid).join(' ');
             ctx.fillText(line1, 0, -width * 0.05);
             ctx.fillText(line2, 0, width * 0.05);
        } else {
             ctx.fillText(text, 0, 0);
        }

        // Animated Circle
        ctx.strokeStyle = accentColor;
        ctx.lineWidth = width * 0.01;
        ctx.beginPath();
        ctx.arc(0, 0, (width * 0.4) + Math.sin(progress * Math.PI * 2) * 20, 0, Math.PI * 2);
        ctx.stroke();

        ctx.restore();
    }

    private static drawKineticSlide(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { text, accentColor } = config;

        ctx.save();
        ctx.translate(width / 2, height / 2);
        ctx.rotate(-Math.PI / 6); // Tilt

        ctx.fillStyle = accentColor;
        ctx.font = `bold ${width * 0.15}px Inter, sans-serif`;
        ctx.textAlign = "center";

        const loopDuration = 1; 
        const slideSpeed = 1000;

        // Repeated text pattern
        for(let i = -6; i <= 6; i++) {
            const dir = i % 2 === 0 ? 1 : -1;
            // Continuous sliding effect
            const xPos = (dir * (progress * slideSpeed) + (i * 50)) % (width + 1000) - (width/2 + 500);

            ctx.globalAlpha = 1 - (Math.abs(i) * 0.12); // Fade out towards edges
            if(ctx.globalAlpha < 0) ctx.globalAlpha = 0;

            ctx.fillText(text.toUpperCase(), xPos, i * (width * 0.14));
        }

        ctx.restore();
    }

    private static drawMatrixRain(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        // Note: For live preview, we strictly clear bg each frame in drawFrame. 
        // For actual Matrix trail feel, we'd need a persistent canvas state, 
        // but for this stateless implementation, we simulate it with gradient opacity.

        ctx.fillStyle = config.accentColor;
        ctx.font = `${width * 0.03}px monospace`;

        const columns = Math.floor(width / (width * 0.03));

        for (let i = 0; i < columns; i++) {
            // Deterministic random-like rain based on column index and progress
            const speed = (Math.sin(i * 99) + 2) * 2000; 
            const offset = Math.cos(i * 50) * height;
            const y = (offset + progress * speed) % height;

            // Draw trail
            for (let j = 0; j < 5; j++) {
                 const char = String.fromCharCode(0x30A0 + Math.abs(Math.floor(Math.sin(i * j + progress) * 96)));
                 ctx.globalAlpha = 1 - (j * 0.2);
                 ctx.fillText(char, i * (width * 0.03), y - j * (width * 0.03));
            }
        }

        // Overlay Text
        ctx.save();
        ctx.globalAlpha = 1;
        ctx.shadowColor = "#000000";
        ctx.shadowBlur = 20;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text, width/2, height/2);
        ctx.restore();
    }

    private static drawCyberGrid(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        // Retro 80s Grid
        const { accentColor } = config;
        const horizon = height * 0.4;

        ctx.save();

        // Sun
        const sunY = horizon - (height * 0.1);
        const sunGradient = ctx.createLinearGradient(0, sunY - 100, 0, sunY + 100);
        sunGradient.addColorStop(0, "#F59E0B"); // Orange
        sunGradient.addColorStop(1, "#EC4899"); // Pink
        ctx.fillStyle = sunGradient;
        ctx.beginPath();
        ctx.arc(width/2, sunY, width * 0.2, 0, Math.PI * 2);
        ctx.fill();

        // Clip bottom
        ctx.beginPath();
        ctx.rect(0, horizon, width, height - horizon);
        ctx.clip();

        // Floor Gradient
        const gridGrad = ctx.createLinearGradient(0, horizon, 0, height);
        gridGrad.addColorStop(0, "rgba(0,0,0,1)");
        gridGrad.addColorStop(1, config.accentColor);
        ctx.fillStyle = gridGrad;
        ctx.fillRect(0, horizon, width, height - horizon);

        // Moving Vertical Lines
        ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
        ctx.lineWidth = 2;
        const perspectiveCenter = width / 2;

        for(let i = -10; i <= 10; i++) {
            const x = perspectiveCenter + (i * width * 0.2) * (1 + Math.sin(progress * 0.1)); // Slight warp

            ctx.beginPath();
            ctx.moveTo(perspectiveCenter, horizon); // Vanishing point
            ctx.lineTo(x + (i * width * 1.5), height);
            ctx.stroke();
        }

        // Moving Horizontal Lines
        const speed = 2000;
        const loopPos = (progress * speed) % 200;

        for (let i = 0; i < 20; i++) {
            const y = horizon + Math.pow(i, 2.5) * 2 + loopPos; // Exponential spacing for perspective
            if (y > height) continue;

            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(width, y);
            ctx.stroke();
        }

        // Text
        ctx.restore();
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = 30;
        ctx.fillStyle = "#ffffff";
        ctx.font = `italic bold ${width * 0.1}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text.toUpperCase(), width/2, height * 0.3);
    }

    private static drawNeuralNet(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor } = config;

        // Simulating particles
        const particleCount = 40;
        const particles = [];

        // Deterministic particle generation based on index
        for(let i=0; i<particleCount; i++) {
            const x = ((i * 137.5) % width);
            const y = ((i * 293.3 + progress * 500) % height);
            particles.push({x, y});
        }

        ctx.fillStyle = accentColor;
        ctx.strokeStyle = accentColor;
        ctx.lineWidth = 1;

        // Draw Connections
        for(let i=0; i<particleCount; i++) {
            const p1 = particles[i];

            // Draw particle
            ctx.beginPath();
            ctx.arc(p1.x, p1.y, 4, 0, Math.PI * 2);
            ctx.fill();

            // Connect nearby
            for(let j=i+1; j<particleCount; j++) {
                const p2 = particles[j];
                const dist = Math.hypot(p1.x - p2.x, p1.y - p2.y);
                if (dist < width * 0.15) {
                    ctx.globalAlpha = 1 - (dist / (width * 0.15));
                    ctx.beginPath();
                    ctx.moveTo(p1.x, p1.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.stroke();
                }
            }
        }

        ctx.globalAlpha = 1;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text, width/2, height/2);
    }

    public async generate(config: VideoConfig): Promise<Blob> {
        const stream = this.canvas.captureStream(config.fps);
        const recorder = new MediaRecorder(stream, {
            mimeType: 'video/webm;codecs=vp9'
        });

        const chunks: BlobPart[] = [];
        recorder.ondataavailable = (e) => {
            if (e.data.size > 0) chunks.push(e.data);
        };

        return new Promise((resolve, reject) => {
            recorder.onstop = () => {
                const blob = new Blob(chunks, { type: 'video/webm' });
                resolve(blob);
            };

            recorder.onerror = (e) => reject(e);

            recorder.start();

            let currentFrame = 0;
            const totalFrames = config.duration * config.fps;

            const renderLoop = () => {
                if (currentFrame >= totalFrames) {
                    recorder.stop();
                    return;
                }

                const progress = currentFrame / totalFrames;

                // Use the static draw method on the internal canvas context
                VideoRenderer.drawFrame(this.ctx, config, progress, this.width, this.height);

                currentFrame++;
                // Use setTimeout to allow the event loop to process MediaRecorder events
                setTimeout(renderLoop, 1000 / config.fps); 
            };

            renderLoop();
        });
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { VideoConfig, AnimationStyle } from '../nova/custom_video_model/types';
import { postCustomVideo } from '../nova/custom_video_model/api';
import { VideoRenderer } from '../nova/custom_video_model/VideoRenderer';
import { XCircleIcon, SparklesIcon, PlayIcon, VideoIcon, CodeBracketIcon, PhotoIcon, CheckBadgeIcon } from './icons';
import { LoadingSpinner } from './LoadingSpinner';
import { motion, AnimatePresence } from 'framer-motion';

interface CustomVideoModalProps {
    onClose: () => void;
    onSuccess: (videoUrl: string, text: string) => void;
}

const CustomVideoModal: React.FC<CustomVideoModalProps> = ({ onClose, onSuccess }) => {
    // State
    const [text, setText] = useState('Create Something');
    const [style, setStyle] = useState<AnimationStyle>('neon-pulse');
    const [duration, setDuration] = useState(5);
    const [backgroundColor, setBackgroundColor] = useState('#000000');
    const [accentColor, setAccentColor] = useState('#00E5FF'); // Cyan default

    const [generating, setGenerating] = useState(false);
    const [progress, setProgress] = useState(0); 

    // Preview Canvas Refs
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const requestRef = useRef<number>();
    const startTimeRef = useRef<number>(0);

    // Live Preview Loop
    useEffect(() => {
        const animate = (time: number) => {
            if (startTimeRef.current === 0) startTimeRef.current = time;

            // Calculate loop progress (0 to 1) based on duration
            const elapsed = time - startTimeRef.current;
            const loopDuration = duration * 1000;
            const progress = (elapsed % loopDuration) / loopDuration;

            if (canvasRef.current) {
                const ctx = canvasRef.current.getContext('2d');
                if (ctx) {
                    const width = canvasRef.current.width;
                    const height = canvasRef.current.height;

                    const config: VideoConfig = {
                        text: text || "Preview Text",
                        style,
                        duration,
                        backgroundColor,
                        accentColor,
                        fps: 30
                    };

                    // Draw frame using the static renderer
                    VideoRenderer.drawFrame(ctx, config, progress, width, height);
                }
            }
            requestRef.current = requestAnimationFrame(animate);
        };

        requestRef.current = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(requestRef.current!);
    }, [text, style, duration, backgroundColor, accentColor]);

    const handleGenerate = async () => {
        if (!text) return;
        setGenerating(true);

        // Mock progress animation
        const progressInterval = setInterval(() => {
            setProgress(prev => Math.min(prev + 5, 95));
        }, 150);

        const config: VideoConfig = {
            text,
            style,
            duration,
            backgroundColor,
            accentColor,
            fps: 30
        };

        try {
            const response = await postCustomVideo(config);

            clearInterval(progressInterval);
            setProgress(100);

            if (response.success && response.videoUrl) {
                onSuccess(response.videoUrl, text);
                onClose();
            } else {
                alert("Failed to generate video: " + response.error);
            }
        } catch (e) {
            console.error(e);
            alert("An error occurred.");
        } finally {
            setGenerating(false);
        }
    };

    const applyPreset = (name: string) => {
        switch(name) {
            case 'Cyberpunk':
                setStyle('cyber-grid');
                setBackgroundColor('#0f0518');
                setAccentColor('#d946ef'); // Fuchsia
                break;
            case 'Midnight':
                setStyle('neon-pulse');
                setBackgroundColor('#000000');
                setAccentColor('#3b82f6'); // Blue
                break;
            case 'Matrix':
                setStyle('matrix-rain');
                setBackgroundColor('#000000');
                setAccentColor('#22c55e'); // Green
                break;
            case 'Luxe':
                setStyle('kinetic-slide');
                setBackgroundColor('#1c1917'); // Stone 900
                setAccentColor('#fbbf24'); // Amber
                break;
            case 'Neural':
                setStyle('neural-net');
                setBackgroundColor('#1e293b'); // Slate 800
                setAccentColor('#2dd4bf'); // Teal
                break;
        }
    };

    const StyleOption = ({ id, label, icon }: { id: AnimationStyle, label: string, icon: React.ReactNode }) => (
        <button 
            onClick={() => setStyle(id)}
            className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all duration-200 ${
                style === id 
                ? 'border-cyan-500 bg-cyan-900/20 shadow-lg shadow-cyan-500/20' 
                : 'border-white/10 bg-white/5 hover:bg-white/10'
            }`}
        >
            <div className={`mb-2 ${style === id ? 'text-cyan-400' : 'text-gray-400'}`}>
                {icon}
            </div>
            <span className={`text-xs font-semibold ${style === id ? 'text-cyan-400' : 'text-gray-400'}`}>{label}</span>
        </button>
    );

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80 backdrop-blur-md p-0 sm:p-4">
            <motion.div 
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className="bg-[#0a0a0a] w-full max-w-5xl h-full sm:h-[85vh] sm:rounded-3xl shadow-2xl overflow-hidden flex flex-col sm:flex-row border border-white/10"
            >
                {/* LEFT SIDE: PREVIEW CANVAS */}
                <div className="w-full sm:w-1/2 h-[40vh] sm:h-full bg-black/50 relative flex items-center justify-center border-b sm:border-b-0 sm:border-r border-white/10 p-4 sm:p-8">
                    <div className="relative w-full max-w-[280px] sm:max-w-[340px] aspect-[9/16] rounded-2xl overflow-hidden shadow-2xl ring-1 ring-white/10">
                        {/* The Canvas acts as the live preview */}
                        <canvas 
                            ref={canvasRef} 
                            width={1080} 
                            height={1920} 
                            className="w-full h-full object-cover"
                        />
                        <div className="absolute top-4 right-4 px-2 py-1 bg-black/60 backdrop-blur-md rounded-md text-[10px] font-mono text-cyan-400 border border-cyan-500/30">
                            LIVE PREVIEW
                        </div>
                    </div>
                </div>

                {/* RIGHT SIDE: CONTROLS */}
                <div className="w-full sm:w-1/2 h-[60vh] sm:h-full flex flex-col bg-[#0f0f0f]">

                    {/* Header */}
                    <div className="p-5 border-b border-white/10 flex justify-between items-center bg-white/5">
                        <h3 className="font-bold text-xl text-white flex items-center gap-2 font-wordmark tracking-tight">
                            <SparklesIcon className="w-5 h-5 text-cyan-400" />
                            Nova Studio
                        </h3>
                        <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors text-gray-400 hover:text-white">
                            <XCircleIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="flex-grow overflow-y-auto p-6 space-y-8 custom-scrollbar">

                        {/* Text Input */}
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Content</label>
                            <textarea 
                                value={text} 
                                onChange={(e) => setText(e.target.value)} 
                                placeholder="What's your story?"
                                rows={2}
                                maxLength={60}
                                className="w-full p-4 bg-black/40 border border-white/10 rounded-xl focus:ring-2 focus:ring-cyan-500 focus:border-transparent outline-none text-lg text-white font-medium placeholder-gray-600 transition-all"
                            />
                        </div>

                        {/* Quick Presets */}
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Instant Styles</label>
                            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                                {['Cyberpunk', 'Midnight', 'Matrix', 'Luxe', 'Neural'].map(p => (
                                    <button 
                                        key={p} 
                                        onClick={() => applyPreset(p)}
                                        className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-full text-xs font-semibold text-gray-300 whitespace-nowrap transition-colors"
                                    >
                                        {p}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Styles Grid */}
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Animation Engine</label>
                            <div className="grid grid-cols-3 gap-3">
                                <StyleOption id="neon-pulse" label="Pulse" icon={<SparklesIcon className="w-6 h-6" />} />
                                <StyleOption id="kinetic-slide" label="Kinetic" icon={<VideoIcon className="w-6 h-6" />} />
                                <StyleOption id="matrix-rain" label="Hacker" icon={<CodeBracketIcon className="w-6 h-6" />} />
                                <StyleOption id="cyber-grid" label="Retro" icon={<PhotoIcon className="w-6 h-6" />} />
                                <StyleOption id="neural-net" label="Neural" icon={<CheckBadgeIcon className="w-6 h-6" />} />
                            </div>
                        </div>

                        {/* Fine Tuning */}
                        <div className="grid grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Duration: {duration}s</label>
                                <input 
                                    type="range" 
                                    min="3" 
                                    max="15" 
                                    value={duration} 
                                    onChange={(e) => setDuration(Number(e.target.value))}
                                    className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Accent Color</label>
                                <div className="flex items-center space-x-3">
                                    <input 
                                        type="color" 
                                        value={accentColor} 
                                        onChange={(e) => setAccentColor(e.target.value)} 
                                        className="w-8 h-8 rounded-full cursor-pointer bg-transparent border-0 p-0" 
                                    />
                                    <span className="text-xs font-mono text-gray-500">{accentColor}</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Footer Action */}
                    <div className="p-6 border-t border-white/10 bg-black/20">
                        <button 
                            onClick={handleGenerate}
                            disabled={!text || generating}
                            className="w-full py-4 px-6 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white font-bold rounded-xl shadow-lg shadow-cyan-900/20 transform active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3"
                        >
                            {generating ? (
                                <>
                                    <LoadingSpinner size="sm" />
                                    <span>Rendering High-Res... {progress}%</span>
                                </>
                            ) : (
                                <>
                                    <PlayIcon className="w-5 h-5 fill-current" />
                                    <span>Generate 1080p Video</span>
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </motion.div>
        </div>
    );
};

