                            disabled={!text || generating}
                            className="w-full py-4 px-6 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white font-bold rounded-xl shadow-lg shadow-cyan-900/20 transform active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3"
                        >
                            {generating ? (
                                <>
                                    <LoadingSpinner size="sm" />
                                    <span>Rendering High-Res... {progress}%</span>
                                </>
                            ) : (
                                <>
                                    <PlayIcon className="w-5 h-5 fill-current" />
                                    <span>Generate 1080p Video</span>
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </motion.div>
        </div>
    );
};

export default CustomVideoModal;

export type AnimationStyle = 'neon-pulse' | 'kinetic-slide' | 'matrix-rain' | 'cyber-grid' | 'neural-net' | 'cosmic-drift' | 'geometric-void';

export type AspectRatio = '9:16' | '16:9' | '1:1';

export interface VideoConfig {
    text: string;
    secondaryText?: string;
    duration: number; // in seconds
    style: AnimationStyle;
    backgroundColor: string; // hex
    accentColor: string; // hex
    fps: number;
    aspectRatio?: AspectRatio;
}

export interface VideoGenerationResponse {
    success: boolean;
    videoUrl?: string;
    error?: string;
    metadata?: {
        duration: number;
        size: number;
        format: string;
    };
}

import { VideoConfig, AnimationStyle } from './types';

export class VideoRenderer {
    private canvas: HTMLCanvasElement;
    private ctx: CanvasRenderingContext2D;
    // Default dimensions, will be overridden in generate based on config
    private width: number = 1080;
    private height: number = 1920; 

    constructor() {
        this.canvas = document.createElement('canvas');
        this.canvas.width = this.width;
        this.canvas.height = this.height;
        const context = this.canvas.getContext('2d');
        if (!context) throw new Error("Could not get 2D context");
        this.ctx = context;
    }

    /**
     * Renders a single frame to the provided context.
     * Static to allow usage in both the MediaRecorder loop and the UI Live Preview.
     */
    public static drawFrame(
        ctx: CanvasRenderingContext2D, 
        config: VideoConfig, 
        progress: number, 
        width: number, 
        height: number
    ) {
        // Clear background
        ctx.fillStyle = config.backgroundColor;
        ctx.fillRect(0, 0, width, height);

        switch (config.style) {
            case 'neon-pulse':
                this.drawNeonPulse(ctx, config, progress, width, height);
                break;
            case 'kinetic-slide':
                this.drawKineticSlide(ctx, config, progress, width, height);
                break;
            case 'matrix-rain':
                this.drawMatrixRain(ctx, config, progress, width, height);
                break;
            case 'cyber-grid':
                this.drawCyberGrid(ctx, config, progress, width, height);
                break;
            case 'neural-net':
                this.drawNeuralNet(ctx, config, progress, width, height);
                break;
            case 'cosmic-drift':
                this.drawCosmicDrift(ctx, config, progress, width, height);
                break;
            case 'geometric-void':
                this.drawGeometricVoid(ctx, config, progress, width, height);
                break;
            default:
                this.drawNeonPulse(ctx, config, progress, width, height);
        }
    }

    private static drawNeonPulse(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { text, accentColor } = config;
        const scale = 1 + Math.sin(progress * Math.PI * 4) * 0.05;

        ctx.save();
        ctx.translate(width / 2, height / 2);
        ctx.scale(scale, scale);

        ctx.shadowBlur = 40 + Math.sin(progress * Math.PI * 4) * 20;
        ctx.shadowColor = accentColor;

        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`; 
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";

        const words = text.split(' ');
        if (text.length > 20) {
             const mid = Math.floor(words.length / 2);
             const line1 = words.slice(0, mid).join(' ');
             const line2 = words.slice(mid).join(' ');
             ctx.fillText(line1, 0, -width * 0.05);
             ctx.fillText(line2, 0, width * 0.05);
        } else {
             ctx.fillText(text, 0, 0);
        }

        ctx.strokeStyle = accentColor;
        ctx.lineWidth = width * 0.01;
        ctx.beginPath();
        ctx.arc(0, 0, (width * 0.4) + Math.sin(progress * Math.PI * 2) * 20, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
    }

    private static drawKineticSlide(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { text, accentColor } = config;
        ctx.save();
        ctx.translate(width / 2, height / 2);
        ctx.rotate(-Math.PI / 6); 
        ctx.fillStyle = accentColor;
        ctx.font = `bold ${width * 0.15}px Inter, sans-serif`;
        ctx.textAlign = "center";
        const slideSpeed = 1000;
        for(let i = -6; i <= 6; i++) {
            const dir = i % 2 === 0 ? 1 : -1;
            const xPos = (dir * (progress * slideSpeed) + (i * 50)) % (width + 1000) - (width/2 + 500);
            ctx.globalAlpha = 1 - (Math.abs(i) * 0.12);
            if(ctx.globalAlpha < 0) ctx.globalAlpha = 0;
            ctx.fillText(text.toUpperCase(), xPos, i * (width * 0.14));
        }
        ctx.restore();
    }

    private static drawMatrixRain(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        ctx.fillStyle = config.accentColor;
        ctx.font = `${width * 0.03}px monospace`;
        const columns = Math.floor(width / (width * 0.03));
        for (let i = 0; i < columns; i++) {
            const speed = (Math.sin(i * 99) + 2) * 2000; 
            const offset = Math.cos(i * 50) * height;
            const y = (offset + progress * speed) % height;
            for (let j = 0; j < 5; j++) {
                 const char = String.fromCharCode(0x30A0 + Math.abs(Math.floor(Math.sin(i * j + progress) * 96)));
                 ctx.globalAlpha = 1 - (j * 0.2);
                 ctx.fillText(char, i * (width * 0.03), y - j * (width * 0.03));
            }
        }
        ctx.save();
        ctx.globalAlpha = 1;
        ctx.shadowColor = "#000000";
        ctx.shadowBlur = 20;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text, width/2, height/2);
        ctx.restore();
    }

    private static drawCyberGrid(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor } = config;
        const horizon = height * 0.4;
        ctx.save();
        const sunY = horizon - (height * 0.1);
        const sunGradient = ctx.createLinearGradient(0, sunY - 100, 0, sunY + 100);
        sunGradient.addColorStop(0, "#F59E0B"); 
        sunGradient.addColorStop(1, "#EC4899"); 
        ctx.fillStyle = sunGradient;
        ctx.beginPath();
        ctx.arc(width/2, sunY, width * 0.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.rect(0, horizon, width, height - horizon);
        ctx.clip();
        const gridGrad = ctx.createLinearGradient(0, horizon, 0, height);
        gridGrad.addColorStop(0, "rgba(0,0,0,1)");
        gridGrad.addColorStop(1, config.accentColor);
        ctx.fillStyle = gridGrad;
        ctx.fillRect(0, horizon, width, height - horizon);
        ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
        ctx.lineWidth = 2;
        const perspectiveCenter = width / 2;
        for(let i = -10; i <= 10; i++) {
            const x = perspectiveCenter + (i * width * 0.2) * (1 + Math.sin(progress * 0.1));
            ctx.beginPath();
            ctx.moveTo(perspectiveCenter, horizon);
            ctx.lineTo(x + (i * width * 1.5), height);
            ctx.stroke();
        }
        const speed = 2000;
        const loopPos = (progress * speed) % 200;
        for (let i = 0; i < 20; i++) {
            const y = horizon + Math.pow(i, 2.5) * 2 + loopPos; 
            if (y > height) continue;
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(width, y);
            ctx.stroke();
        }
        ctx.restore();
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = 30;
        ctx.fillStyle = "#ffffff";
        ctx.font = `italic bold ${width * 0.1}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text.toUpperCase(), width/2, height * 0.3);
    }

    private static drawNeuralNet(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor } = config;
        const particleCount = 40;
        const particles = [];
        for(let i=0; i<particleCount; i++) {
            const x = ((i * 137.5) % width);
            const y = ((i * 293.3 + progress * 500) % height);
            particles.push({x, y});
        }
        ctx.fillStyle = accentColor;
        ctx.strokeStyle = accentColor;
        ctx.lineWidth = 1;
        for(let i=0; i<particleCount; i++) {
            const p1 = particles[i];
            ctx.beginPath();
            ctx.arc(p1.x, p1.y, 4, 0, Math.PI * 2);
            ctx.fill();
            for(let j=i+1; j<particleCount; j++) {
                const p2 = particles[j];
                const dist = Math.hypot(p1.x - p2.x, p1.y - p2.y);
                if (dist < width * 0.15) {
                    ctx.globalAlpha = 1 - (dist / (width * 0.15));
                    ctx.beginPath();
                    ctx.moveTo(p1.x, p1.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.stroke();
                }
            }
        }
        ctx.globalAlpha = 1;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text, width/2, height/2);
    }

    private static drawCosmicDrift(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor } = config;

        // Background Gradient
        const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, width);
        grad.addColorStop(0, "#1e1b4b"); // Indigo 950
        grad.addColorStop(1, "#000000");
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, width, height);

        // Stars
        ctx.fillStyle = "#ffffff";
        const starCount = 100;
        for (let i = 0; i < starCount; i++) {
            const r = (i * 123.45) % width; // pseudo-random seed based on index
            const angle = (i * 32.1 + progress * Math.PI) % (Math.PI * 2);
            const dist = (i * 10 + progress * 1000) % (Math.max(width, height) / 1.5);

            const x = width/2 + Math.cos(angle + i) * dist;
            const y = height/2 + Math.sin(angle + i) * dist;

            const size = (dist / width) * 4;
            ctx.globalAlpha = Math.min(1, dist / (width/4));

            ctx.beginPath();
            ctx.arc(x, y, size, 0, Math.PI * 2);
            ctx.fill();
        }

        // Nebula Cloud (Simulated)
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = accentColor;
        const cloudX = width/2 + Math.sin(progress * Math.PI) * 200;
        const cloudY = height/2 + Math.cos(progress * Math.PI) * 200;
        ctx.filter = "blur(100px)"; // heavy blur for gaseous look
        ctx.beginPath();
        ctx.arc(cloudX, cloudY, width/3, 0, Math.PI * 2);
        ctx.fill();
        ctx.filter = "none";

        // Text
        ctx.globalAlpha = 1;
        ctx.save();
        ctx.translate(width/2, height/2);
        const textScale = 1 + Math.sin(progress * Math.PI * 2) * 0.1;
        ctx.scale(textScale, textScale);
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = 50;
        ctx.fillStyle = "#ffffff";
        ctx.font = `900 ${width * 0.1}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text.toUpperCase(), 0, 0);
        ctx.restore();
    }

    private static drawGeometricVoid(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor, backgroundColor } = config;

        ctx.fillStyle = backgroundColor;
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = accentColor;
        ctx.lineWidth = 3;
        const centerX = width / 2;
        const centerY = height / 2;
        const shapeCount = 10;
        const maxRadius = width * 0.8;

        for (let i = 0; i < shapeCount; i++) {
            const p = (progress + i/shapeCount) % 1;
            const size = p * maxRadius;
            const rotation = p * Math.PI * 2;
            const opacity = 1 - p;

            ctx.save();
            ctx.translate(centerX, centerY);
            ctx.rotate(rotation);
            ctx.globalAlpha = opacity;

            ctx.beginPath();
            // Draw Hexagon
            for (let j = 0; j < 6; j++) {
                const angle = (j * Math.PI * 2) / 6;
                const x = Math.cos(angle) * size;
                const y = Math.sin(angle) * size;
                if (j === 0) ctx.moveTo(x, y);
                else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();
            ctx.restore();
        }

        // Central Text
        ctx.globalAlpha = 1;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = 20;
        ctx.fillText(config.text, centerX, centerY);
    }

    public async generate(config: VideoConfig): Promise<Blob> {
        // Set dimensions based on aspect ratio
        if (config.aspectRatio === '16:9') {
            this.canvas.width = 1920;
            this.canvas.height = 1080;
        } else if (config.aspectRatio === '1:1') {
            this.canvas.width = 1080;
            this.canvas.height = 1080;
        } else {
            // Default 9:16
            this.canvas.width = 1080;
            this.canvas.height = 1920;
        }

        // Update context reference if canvas resized (though getContext usually persists, good practice)
        this.ctx = this.canvas.getContext('2d')!;

        const stream = this.canvas.captureStream(config.fps);
        const recorder = new MediaRecorder(stream, {
            mimeType: 'video/webm;codecs=vp9'
        });

        const chunks: BlobPart[] = [];
        recorder.ondataavailable = (e) => {
            if (e.data.size > 0) chunks.push(e.data);
        };

        return new Promise((resolve, reject) => {
            recorder.onstop = () => {
                const blob = new Blob(chunks, { type: 'video/webm' });
                resolve(blob);
            };

            recorder.onerror = (e) => reject(e);

            recorder.start();

            let currentFrame = 0;
            const totalFrames = config.duration * config.fps;

            const renderLoop = () => {
                if (currentFrame >= totalFrames) {
                    recorder.stop();
                    return;
                }

                const progress = currentFrame / totalFrames;

                // Use the static draw method on the internal canvas context
                VideoRenderer.drawFrame(this.ctx, config, progress, this.canvas.width, this.canvas.height);

                currentFrame++;
                setTimeout(renderLoop, 1000 / config.fps); 
            };

            renderLoop();
        });
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { VideoConfig, AnimationStyle, AspectRatio } from '../nova/custom_video_model/types';
import { postCustomVideo } from '../nova/custom_video_model/api';
import { VideoRenderer } from '../nova/custom_video_model/VideoRenderer';
import { XCircleIcon, SparklesIcon, PlayIcon, VideoIcon, CodeBracketIcon, PhotoIcon, CheckBadgeIcon } from './icons';
import { LoadingSpinner } from './LoadingSpinner';
import { motion, AnimatePresence } from 'framer-motion';

interface CustomVideoModalProps {
    onClose: () => void;
    onSuccess: (videoUrl: string, text: string) => void;
}

const CustomVideoModal: React.FC<CustomVideoModalProps> = ({ onClose, onSuccess }) => {
    // State
    const [text, setText] = useState('Create Something');
    const [style, setStyle] = useState<AnimationStyle>('cosmic-drift');
    const [duration, setDuration] = useState(5);
    const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
    const [backgroundColor, setBackgroundColor] = useState('#0a0a0a');
    const [accentColor, setAccentColor] = useState('#6366f1'); // Indigo

    const [generating, setGenerating] = useState(false);
    const [progress, setProgress] = useState(0); 

    // Preview Canvas Refs
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const requestRef = useRef<number>(0);
    const startTimeRef = useRef<number>(0);

    // Live Preview Loop
    useEffect(() => {
        const animate = (time: number) => {
            if (startTimeRef.current === 0) startTimeRef.current = time;

            const elapsed = time - startTimeRef.current;
            const loopDuration = duration * 1000;
            const progress = (elapsed % loopDuration) / loopDuration;

            if (canvasRef.current) {
                const ctx = canvasRef.current.getContext('2d');
                if (ctx) {
                    const width = canvasRef.current.width;
                    const height = canvasRef.current.height;

                    const config: VideoConfig = {
                        text: text || "Nova AI",
                        style,
                        duration,
                        backgroundColor,
                        accentColor,
                        fps: 30,
                        aspectRatio
                    };

                    VideoRenderer.drawFrame(ctx, config, progress, width, height);
                }
            }
            requestRef.current = requestAnimationFrame(animate);
        };

        requestRef.current = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(requestRef.current!);
    }, [text, style, duration, backgroundColor, accentColor, aspectRatio]);

    const handleGenerate = async () => {
        if (!text) return;
        setGenerating(true);

        const progressInterval = setInterval(() => {
            setProgress(prev => Math.min(prev + 5, 95));
        }, 150);

        const config: VideoConfig = {
            text,
            style,
            duration,
            backgroundColor,
            accentColor,
            fps: 30,
            aspectRatio
        };

        try {
            const response = await postCustomVideo(config);
            clearInterval(progressInterval);
            setProgress(100);

            if (response.success && response.videoUrl) {
                onSuccess(response.videoUrl, text);
                onClose();
            } else {
                alert("Failed to generate video: " + response.error);
            }
        } catch (e) {
            console.error(e);
            alert("An error occurred.");
        } finally {
            setGenerating(false);
        }
    };

    const applyPreset = (name: string) => {
        switch(name) {
            case 'Galactic':
                setStyle('cosmic-drift');
                setBackgroundColor('#000000');
                setAccentColor('#818cf8');
                break;
            case 'Void':
                setStyle('geometric-void');
                setBackgroundColor('#18181b');
                setAccentColor('#2dd4bf');
                break;
            case 'Cyberpunk':
                setStyle('cyber-grid');
                setBackgroundColor('#0f0518');
                setAccentColor('#d946ef');
                break;
            case 'Matrix':
                setStyle('matrix-rain');
                setBackgroundColor('#000000');
                setAccentColor('#22c55e');
                break;
            case 'Neon':
                setStyle('neon-pulse');
                setBackgroundColor('#000000');
                setAccentColor('#f43f5e');
                break;
        }
    };

    const StyleOption = ({ id, label, icon }: { id: AnimationStyle, label: string, icon: React.ReactNode }) => (
        <button 
            onClick={() => setStyle(id)}
            className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all duration-200 relative overflow-hidden group ${
                style === id 
                ? 'border-indigo-500 bg-indigo-500/10' 
                : 'border-white/5 bg-white/5 hover:bg-white/10'
            }`}
        >
            <div className={`mb-2 transition-colors ${style === id ? 'text-indigo-400' : 'text-gray-400 group-hover:text-gray-300'}`}>
                {icon}
            </div>
            <span className={`text-[10px] font-medium tracking-wide uppercase ${style === id ? 'text-indigo-400' : 'text-gray-500 group-hover:text-gray-400'}`}>{label}</span>
            {style === id && <div className="absolute inset-0 border-2 border-indigo-500 rounded-xl pointer-events-none" />}
        </button>
    );

    const AspectButton = ({ id, label }: { id: AspectRatio, label: string }) => (
        <button
            onClick={() => setAspectRatio(id)}
            className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-all ${
                aspectRatio === id 
                ? 'bg-white text-black' 
                : 'bg-white/10 text-gray-400 hover:text-white'
            }`}
        >
            {label}
        </button>
    );

    // Determine canvas dimensions for CSS preview based on selection
    const getPreviewDimensions = () => {
        if (aspectRatio === '16:9') return 'aspect-video w-full';
        if (aspectRatio === '1:1') return 'aspect-square w-full max-w-[400px]';
        return 'aspect-[9/16] w-full max-w-[280px]'; // 9:16
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 backdrop-blur-xl p-0 sm:p-6 font-sans">
            <motion.div 
                initial={{ opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.98 }}
                className="bg-[#050505] w-full max-w-6xl h-full sm:h-[90vh] sm:rounded-3xl shadow-2xl overflow-hidden flex flex-col sm:flex-row border border-white/5"
            >
                {/* LEFT: LIVE PREVIEW AREA */}
                <div className="w-full sm:w-[55%] h-[40vh] sm:h-full bg-grid-pattern relative flex flex-col items-center justify-center border-b sm:border-b-0 sm:border-r border-white/5 bg-[#080808]">

                    {/* Header overlay on preview */}
                    <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-start pointer-events-none">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
                            <span className="text-[10px] font-mono text-green-500 uppercase tracking-widest">Live Engine</span>
                        </div>
                    </div>

                    {/* Canvas Container */}
                    <div className={`relative transition-all duration-500 ease-in-out ${getPreviewDimensions()} rounded-lg overflow-hidden shadow-2xl ring-1 ring-white/10 bg-black`}>
                        <canvas 
                            ref={canvasRef} 
                            // Internal resolution matches the aspect ratio logic
                            width={aspectRatio === '16:9' ? 1920 : 1080} 
                            height={aspectRatio === '16:9' ? 1080 : (aspectRatio === '1:1' ? 1080 : 1920)} 
                            className="w-full h-full object-cover"
                        />
                    </div>

                    {/* Aspect Ratio Controls (Floating) */}
                    <div className="absolute bottom-6 flex gap-2 bg-black/50 backdrop-blur-md p-1.5 rounded-xl border border-white/10">
                        <AspectButton id="9:16" label="9:16" />
                        <AspectButton id="16:9" label="16:9" />
                        <AspectButton id="1:1" label="1:1" />
                    </div>
                </div>

                {/* RIGHT: COMMAND CENTER */}
                <div className="w-full sm:w-[45%] h-[60vh] sm:h-full flex flex-col bg-[#050505]">

                    <div className="p-6 border-b border-white/5 flex justify-between items-center">
                        <h3 className="text-lg font-medium text-white flex items-center gap-2">
                            <span className="text-indigo-500"><SparklesIcon className="w-5 h-5"/></span>
                            Nova Video Gen
                        </h3>
                        <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors text-gray-500 hover:text-white">
                            <XCircleIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="flex-grow overflow-y-auto p-6 space-y-8 custom-scrollbar">

                        {/* Prompt Input */}
                        <div className="space-y-3">
                            <label className="text-[11px] font-bold text-gray-500 uppercase tracking-widest">Prompt</label>
                            <div className="relative group">
                                <textarea 
                                    value={text} 
                                    onChange={(e) => setText(e.target.value)} 
                                    placeholder="Enter text to animate..."
