                                    <span className="text-[10px] font-mono text-gray-600 uppercase">{accentColor}</span>
                                    <input 
                                        type="color" 
                                        value={accentColor} 
                                        onChange={(e) => setAccentColor(e.target.value)} 
                                        className="w-6 h-6 rounded-full cursor-pointer bg-transparent border-0 p-0" 
                                    />
