                    {/* Footer */}
                    <div className="p-6 border-t border-white/5 bg-[#080808]">
                        <button 
                            onClick={handleGenerate}
                            disabled={!text || generating}
                            className="group w-full py-4 px-6 bg-white text-black font-bold rounded-xl hover:bg-gray-200 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3 relative overflow-hidden"
                        >
                            {generating ? (
                                <>
                                    <LoadingSpinner size="sm" />
                                    <span className="text-sm">Processing... {progress}%</span>
                                </>
                            ) : (
                                <>
