                                    <PlayIcon className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                                </>
                            )}
                        </button>
                        <p className="text-center text-[10px] text-gray-600 mt-3 font-mono">
                            NOVA RENDER ENGINE V2.1 • {aspectRatio} • 1080P
                        </p>
                    </div>
                </div>
            </motion.div>
        </div>
    );
};

export default CustomVideoModal;

export type AnimationStyle = 'neon-pulse' | 'kinetic-slide' | 'matrix-rain' | 'cyber-grid' | 'neural-net' | 'cosmic-drift' | 'geometric-void';

export type AspectRatio = '9:16' | '16:9' | '1:1';

export type GenerationMode = 'procedural' | 'ai-generative';

export interface VideoConfig {
    // Shared
    mode?: GenerationMode;
    text: string; // Used as prompt for AI
    duration: number; // in seconds
    aspectRatio?: AspectRatio;

    // Procedural specific
    style?: AnimationStyle;
    backgroundColor?: string; // hex
    accentColor?: string; // hex
    secondaryText?: string;
    fps?: number;

    // AI specific
    referenceImage?: string; // base64
    enhancePrompt?: boolean;
}

export interface VideoGenerationResponse {
    success: boolean;
    videoUrl?: string;
    error?: string;
    metadata?: {
        duration: number;
        size: number;
        format: string;
        engine: string;
    };
}

import { VideoConfig, VideoGenerationResponse } from './types';
import { VideoRenderer } from './VideoRenderer';
import { GoogleGenAI } from "@google/genai";

/**
 * Routes the generation request to either the Canvas Renderer or the Veo AI Model.
 */
export async function postCustomVideo(config: VideoConfig): Promise<VideoGenerationResponse> {
    if (config.mode === 'ai-generative') {
        return generateVeoVideo(config);
    } else {
        return generateProceduralVideo(config);
    }
}

async function generateProceduralVideo(config: VideoConfig): Promise<VideoGenerationResponse> {
    try {
        const renderer = new VideoRenderer();
        const videoBlob = await renderer.generate({
            ...config,
            style: config.style || 'neon-pulse',
            backgroundColor: config.backgroundColor || '#000000',
            accentColor: config.accentColor || '#00E5FF',
            fps: config.fps || 30
        });
        const videoUrl = URL.createObjectURL(videoBlob);

        return {
            success: true,
            videoUrl: videoUrl,
            metadata: {
                duration: config.duration,
                size: videoBlob.size,
                format: 'video/webm',
                engine: 'Nova Canvas Engine v2.1'
            }
        };
    } catch (error: any) {
        console.error("Procedural Video Gen Error:", error);
        return {
            success: false,
            error: error.message || "Unknown error during video generation"
        };
    }
}

async function generateVeoVideo(config: VideoConfig): Promise<VideoGenerationResponse> {
    try {
        // 1. Check for API Key (Client-side check helper expected to be run before calling this, but double check)
        if (!process.env.API_KEY) {
            throw new Error("API Key not found. Please connect your Google AI Studio key.");
        }

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // 2. Prepare Config
        // Veo supports '16:9' or '9:16'. Map '1:1' to '16:9' or throw error, or let backend decide.
        // We will default to 16:9 if 1:1 is requested as Veo is cinematic.
        const targetAspectRatio = config.aspectRatio === '9:16' ? '9:16' : '16:9';

        console.log(`[Nova Veo] Starting generation. Prompt: "${config.text.slice(0, 20)}..." Image: ${!!config.referenceImage}`);

        // 3. Call Generate Videos
        let operation;

        if (config.referenceImage) {
            // Remove data URL header if present
            const cleanBase64 = config.referenceImage.split(',')[1] || config.referenceImage;

            operation = await ai.models.generateVideos({
                model: 'veo-3.1-generate-preview',
                prompt: config.text, // Prompt is optional when image provided, but we use it for control
                image: {
                    imageBytes: cleanBase64,
                    mimeType: 'image/png', // Assuming PNG/JPEG, API is flexible usually
                },
                config: {
                    numberOfVideos: 1,
                    resolution: '720p', // Preview models usually 720p
                    aspectRatio: targetAspectRatio
                }
            });
        } else {
            operation = await ai.models.generateVideos({
                model: 'veo-3.1-generate-preview',
                prompt: config.text,
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: targetAspectRatio
                }
            });
        }

        // 4. Poll for completion
        // Veo generation takes time (10s - 60s+).
        let attempts = 0;
        const maxAttempts = 60; // 5 minutes approx with 5s delay

        while (!operation.done && attempts < maxAttempts) {
            await new Promise(resolve => setTimeout(resolve, 5000));
            operation = await ai.operations.getVideosOperation({operation: operation});
            attempts++;
            console.log(`[Nova Veo] Polling... Attempt ${attempts}`);
        }

        if (!operation.done) {
            throw new Error("Video generation timed out.");
        }

        // 5. Retrieve Video
        const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (!videoUri) {
            throw new Error("Generation completed but no video URI was returned.");
        }

        // 6. Fetch the actual video bytes using the API key
        // The URI requires the key appended
        const fetchUrl = `${videoUri}&key=${process.env.API_KEY}`;
        const response = await fetch(fetchUrl);

        if (!response.ok) {
            throw new Error(`Failed to download video bytes: ${response.statusText}`);
        }

        const videoBlob = await response.blob();
        const videoUrl = URL.createObjectURL(videoBlob);

        return {
            success: true,
            videoUrl: videoUrl,
            metadata: {
                duration: 5, // Veo previews are typically ~5s
                size: videoBlob.size,
                format: 'video/mp4',
                engine: 'Gemini Veo 3.1'
            }
        };

    } catch (error: any) {
        console.error("Veo AI Gen Error:", error);

        let friendlyError = error.message || "Failed to generate video.";
        if (error.message.includes("403") || error.message.includes("PERMISSION_DENIED")) {
            friendlyError = "Access Denied. Please ensure you are using a paid API Key with access to the Veo model.";
        }

        return {
            success: false,
            error: friendlyError
        };
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { VideoConfig, AnimationStyle, AspectRatio, GenerationMode } from '../nova/custom_video_model/types';
import { postCustomVideo } from '../nova/custom_video_model/api';
import { VideoRenderer } from '../nova/custom_video_model/VideoRenderer';
import { XCircleIcon, SparklesIcon, PlayIcon, VideoIcon, CodeBracketIcon, PhotoIcon, CheckBadgeIcon, ArrowUpTrayIcon, PaperClipIcon, VideoCameraIcon, TrashIcon } from './icons';
import { LoadingSpinner } from './LoadingSpinner';
import { motion, AnimatePresence } from 'framer-motion';
import { GoogleGenAI } from "@google/genai";

interface CustomVideoModalProps {
    onClose: () => void;
    onSuccess: (videoUrl: string, text: string) => void;
}

const CustomVideoModal: React.FC<CustomVideoModalProps> = ({ onClose, onSuccess }) => {
    // --- Global State ---
    const [mode, setMode] = useState<GenerationMode>('procedural'); // 'procedural' or 'ai-generative'
    const [text, setText] = useState('');
    const [aspectRatio, setAspectRatio] = useState<AspectRatio>('16:9');
    const [generating, setGenerating] = useState(false);
    const [progress, setProgress] = useState(0);
    const [resultVideoUrl, setResultVideoUrl] = useState<string | null>(null);
    const [generationError, setGenerationError] = useState<string | null>(null);

    // --- Procedural Mode State ---
    const [style, setStyle] = useState<AnimationStyle>('cosmic-drift');
    const [duration, setDuration] = useState(5);
    const [backgroundColor, setBackgroundColor] = useState('#0a0a0a');
    const [accentColor, setAccentColor] = useState('#6366f1');
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const requestRef = useRef<number>(0);
    const startTimeRef = useRef<number>(0);

    // --- AI Mode State ---
    const [referenceImage, setReferenceImage] = useState<string | null>(null);
    const [enhancing, setEnhancing] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // --- Live Preview Loop (Procedural Only) ---
    useEffect(() => {
        if (mode !== 'procedural') {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
            return;
        }

        const animate = (time: number) => {
            if (startTimeRef.current === 0) startTimeRef.current = time;
            const elapsed = time - startTimeRef.current;
            const loopDuration = duration * 1000;
            const progress = (elapsed % loopDuration) / loopDuration;

            if (canvasRef.current) {
                const ctx = canvasRef.current.getContext('2d');
                if (ctx) {
                    const width = canvasRef.current.width;
                    const height = canvasRef.current.height;
                    const config: VideoConfig = {
                        text: text || "Nova AI",
                        style,
                        duration,
                        backgroundColor,
                        accentColor,
                        fps: 30,
                        aspectRatio,
                        mode: 'procedural'
                    };
                    VideoRenderer.drawFrame(ctx, config, progress, width, height);
                }
            }
            requestRef.current = requestAnimationFrame(animate);
        };
        requestRef.current = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(requestRef.current!);
    }, [text, style, duration, backgroundColor, accentColor, aspectRatio, mode]);

    // --- Handlers ---

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setReferenceImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const enhancePrompt = async () => {
        if (!text || enhancing) return;
        setEnhancing(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const result = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: `Rewrite the following video prompt to be more cinematic, descriptive, and detailed for an AI video generator. Keep it under 40 words. Prompt: "${text}"`,
            });
            if (result.text) setText(result.text.replace(/^"|"$/g, ''));
        } catch (e) {
            console.error("Enhance failed", e);
        } finally {
            setEnhancing(false);
        }
    };

    const checkApiKey = async () => {
        try {
            if ((window as any).aistudio) {
                const hasKey = await (window as any).aistudio.hasSelectedApiKey();
                if (!hasKey) {
                    await (window as any).aistudio.openSelectKey();
                    // Assume success or retry will happen on generate
                }
                return true;
            }
            return false;
        } catch (e) {
            console.error("Key check failed", e);
            return false;
        }
    };

    const handleGenerate = async () => {
        if (!text && !referenceImage) return;
        setGenerationError(null);
        setGenerating(true);
        setResultVideoUrl(null);

        // Mock progress for UI feedback
        let progressVal = 0;
        const progressInterval = setInterval(() => {
            progressVal = Math.min(progressVal + (mode === 'ai-generative' ? 1 : 5), 90);
            setProgress(progressVal);
        }, mode === 'ai-generative' ? 500 : 150);

        try {
            if (mode === 'ai-generative') {
                await checkApiKey();
            }

            const config: VideoConfig = {
                mode,
                text,
                style,
                duration,
                backgroundColor,
                accentColor,
                fps: 30,
                aspectRatio,
                referenceImage: referenceImage || undefined
            };

            const response = await postCustomVideo(config);

            clearInterval(progressInterval);
            setProgress(100);

            if (response.success && response.videoUrl) {
                setResultVideoUrl(response.videoUrl);
                // Don't auto close, let user preview
            } else {
                setGenerationError(response.error || "Generation failed.");
            }
        } catch (e: any) {
            clearInterval(progressInterval);
            setGenerationError(e.message || "An unexpected error occurred.");
        } finally {
            setGenerating(false);
        }
    };

    const handleSaveAndClose = () => {
        if (resultVideoUrl) {
            onSuccess(resultVideoUrl, text);
            onClose();
        }
    };

    const applyPreset = (name: string) => {
        // ... (Existing preset logic for Procedural)
        switch(name) {
            case 'Galactic': setStyle('cosmic-drift'); setBackgroundColor('#000000'); setAccentColor('#818cf8'); break;
            case 'Void': setStyle('geometric-void'); setBackgroundColor('#18181b'); setAccentColor('#2dd4bf'); break;
            case 'Cyberpunk': setStyle('cyber-grid'); setBackgroundColor('#0f0518'); setAccentColor('#d946ef'); break;
            case 'Matrix': setStyle('matrix-rain'); setBackgroundColor('#000000'); setAccentColor('#22c55e'); break;
            case 'Neon': setStyle('neon-pulse'); setBackgroundColor('#000000'); setAccentColor('#f43f5e'); break;
        }
    };

    // --- Components ---

    const ModeToggle = () => (
        <div className="flex bg-white/5 p-1 rounded-xl mb-6 border border-white/10">
            <button 
                onClick={() => setMode('procedural')} 
                className={`flex-1 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-center gap-2 ${mode === 'procedural' ? 'bg-white text-black shadow-md' : 'text-gray-400 hover:text-white'}`}
            >
                <SparklesIcon className="w-4 h-4" /> Motion Graphics
            </button>
            <button 
                onClick={() => setMode('ai-generative')} 
                className={`flex-1 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-center gap-2 ${mode === 'ai-generative' ? 'bg-gradient-to-r from-indigo-500 to-purple-600 text-white shadow-md' : 'text-gray-400 hover:text-white'}`}
            >
                <VideoCameraIcon className="w-4 h-4" /> Cinematic AI
            </button>
        </div>
    );

    const AspectButton = ({ id, label }: { id: AspectRatio, label: string }) => (
        <button onClick={() => setAspectRatio(id)} className={`px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-wider transition-all border ${aspectRatio === id ? 'bg-white text-black border-white' : 'bg-transparent text-gray-500 border-white/10 hover:border-white/30'}`}>{label}</button>
    );

    const getPreviewDimensions = () => {
        if (aspectRatio === '16:9') return 'aspect-video w-full';
        if (aspectRatio === '1:1') return 'aspect-square w-full max-w-[400px]';
        return 'aspect-[9/16] w-full max-w-[280px]';
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 backdrop-blur-xl p-0 sm:p-6 font-sans">
            <motion.div 
                initial={{ opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.98 }}
                className="bg-[#050505] w-full max-w-6xl h-full sm:h-[90vh] sm:rounded-3xl shadow-2xl overflow-hidden flex flex-col sm:flex-row border border-white/10"
            >
                {/* LEFT: PREVIEW AREA */}
                <div className="w-full sm:w-[60%] h-[40vh] sm:h-full relative flex flex-col items-center justify-center border-b sm:border-b-0 sm:border-r border-white/5 bg-[#020202]">
                    <div className="absolute top-6 left-6 z-10 flex items-center gap-3">
                        <div className={`px-2 py-1 rounded-md text-[10px] font-mono border ${mode === 'ai-generative' ? 'border-purple-500/50 text-purple-400 bg-purple-500/10' : 'border-green-500/50 text-green-400 bg-green-500/10'}`}>
                            {mode === 'ai-generative' ? 'GEMINI VEO ENGINE' : 'CANVAS ENGINE'}
                        </div>
                        {generating && <span className="text-[10px] text-gray-500 animate-pulse">RENDERING...</span>}
                    </div>

                    <div className={`relative transition-all duration-500 ease-in-out ${getPreviewDimensions()} rounded-xl overflow-hidden shadow-2xl ring-1 ring-white/10 bg-[#0a0a0a]`}>
                        {resultVideoUrl ? (
                            <video src={resultVideoUrl} autoPlay loop controls className="w-full h-full object-cover" />
                        ) : mode === 'procedural' ? (
                            <canvas 
                                ref={canvasRef} 
                                width={aspectRatio === '16:9' ? 1920 : 1080} 
                                height={aspectRatio === '16:9' ? 1080 : (aspectRatio === '1:1' ? 1080 : 1920)} 
                                className="w-full h-full object-cover"
                            />
                        ) : (
                            <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 bg-[#080808]">
                                {generating ? (
                                    <div className="flex flex-col items-center gap-4">
                                        <div className="w-16 h-16 rounded-full border-4 border-indigo-500/30 border-t-indigo-500 animate-spin"></div>
                                        <p className="text-xs font-mono text-indigo-400 animate-pulse">DREAMING SCENE...</p>
                                    </div>
                                ) : (
                                    <>
                                        <VideoCameraIcon className="w-16 h-16 opacity-20 mb-4" />
                                        <p className="text-xs font-mono opacity-50">PREVIEW NOT AVAILABLE IN AI MODE</p>
                                        <p className="text-[10px] opacity-30 mt-1">Video generates upon request</p>
                                    </>
                                )}
                            </div>
                        )}

                        {/* Error Overlay */}
                        {generationError && (
                            <div className="absolute inset-0 bg-black/80 flex items-center justify-center p-6 text-center">
                                <div>
                                    <XCircleIcon className="w-10 h-10 text-red-500 mx-auto mb-2" />
                                    <p className="text-sm text-red-200">{generationError}</p>
                                    <button onClick={() => setGenerationError(null)} className="mt-4 px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-xs">Dismiss</button>
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="absolute bottom-6 flex gap-2 bg-black/50 backdrop-blur-md p-1.5 rounded-xl border border-white/10">
                        <AspectButton id="16:9" label="16:9 Cinema" />
                        <AspectButton id="9:16" label="9:16 Social" />
                        <AspectButton id="1:1" label="1:1 Square" />
                    </div>
                </div>

                {/* RIGHT: CONTROLS */}
                <div className="w-full sm:w-[40%] h-[60vh] sm:h-full flex flex-col bg-[#050505]">
                    <div className="p-6 border-b border-white/5 flex justify-between items-center">
                        <h3 className="text-lg font-medium text-white flex items-center gap-2">
                            <span className="text-indigo-500"><SparklesIcon className="w-5 h-5"/></span>
                            Nova Studio
                        </h3>
                        <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors text-gray-500 hover:text-white">
                            <XCircleIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="flex-grow overflow-y-auto p-6 space-y-6 custom-scrollbar">
