import { VideoConfig, AnimationStyle } from './types';

class AudioGenerator {
    private ctx: AudioContext;
    private dest: MediaStreamAudioDestinationNode;

    constructor() {
        this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
        this.dest = this.ctx.createMediaStreamDestination();
    }

    public getStream(): MediaStream {
        return this.dest.stream;
    }

    public async generateSoundtrack(mood: string, duration: number) {
        const ctx = this.ctx;
        const dest = this.dest;
        const now = ctx.currentTime;
        const end = now + duration;

        // Master Gain for fade in/out
        const masterGain = ctx.createGain();
        masterGain.connect(dest);
        masterGain.gain.setValueAtTime(0, now);
        masterGain.gain.linearRampToValueAtTime(0.5, now + 1); // Fade in
        masterGain.gain.linearRampToValueAtTime(0, end); // Fade out

        if (mood === 'Cyberpunk Synth') {
            // Arpeggiated Bass
            const osc = ctx.createOscillator();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(55, now); // A1
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.setValueAtTime(400, now);
            filter.frequency.linearRampToValueAtTime(2000, end);
            osc.connect(filter);
            filter.connect(masterGain);
            osc.start(now);
            osc.stop(end);
        } else if (mood === 'Epic Score') {
            // Orchestral Drone (Low strings emulation)
            [110, 164.8, 220].forEach(freq => { // A Major chord spread
                const osc = ctx.createOscillator();
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(freq, now);
                const gain = ctx.createGain();
                gain.gain.value = 0.2;
                osc.connect(gain);
                gain.connect(masterGain);
                osc.start(now);
                osc.stop(end);
            });
        } else if (mood === 'Nature Sounds') {
            // Pink Noise for wind/rain
            const bufferSize = 2 * ctx.sampleRate;
            const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const output = noiseBuffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) {
                const white = Math.random() * 2 - 1;
                output[i] = (lastOut + (0.02 * white)) / 1.02;
                lastOut = output[i];
                output[i] *= 3.5; 
            }
            const noise = ctx.createBufferSource();
            noise.buffer = noiseBuffer;
            noise.loop = true;
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.value = 800;
            noise.connect(filter);
            filter.connect(masterGain);
            noise.start(now);
            noise.stop(end);
        } else if (mood === 'Cinematic Ambience') {
             // Deep Space Drone
             const osc1 = ctx.createOscillator();
             osc1.frequency.value = 60;
             const osc2 = ctx.createOscillator();
             osc2.frequency.value = 62; // Detuned
             const gain = ctx.createGain();
             gain.gain.value = 0.3;
             osc1.connect(gain);
             osc2.connect(gain);
             gain.connect(masterGain);
             osc1.start(now);
             osc2.start(now);
             osc1.stop(end);
             osc2.stop(end);
        }
        // Default/Silent does nothing extra
    }

    public close() {
        this.ctx.close();
    }
}

// Global helper for noise generation
let lastOut = 0;

export class VideoRenderer {
    private canvas: HTMLCanvasElement;
    private ctx: CanvasRenderingContext2D;
    private width: number = 1080;
    private height: number = 1920; 

    constructor() {
        this.canvas = document.createElement('canvas');
        this.canvas.width = this.width;
        this.canvas.height = this.height;
        const context = this.canvas.getContext('2d');
        if (!context) throw new Error("Could not get 2D context");
        this.ctx = context;
    }

    public static drawFrame(
        ctx: CanvasRenderingContext2D, 
        config: VideoConfig, 
        progress: number, 
        width: number, 
        height: number,
        imageElement?: HTMLImageElement
    ) {
        // Clear background
        ctx.fillStyle = config.backgroundColor || '#000000';
        ctx.fillRect(0, 0, width, height);

        if (config.mode === 'ai-generative' && imageElement) {
            this.drawCinematicImage(ctx, imageElement, progress, width, height, config.text);
            return;
        }

        switch (config.style) {
            case 'neon-pulse': this.drawNeonPulse(ctx, config, progress, width, height); break;
            case 'kinetic-slide': this.drawKineticSlide(ctx, config, progress, width, height); break;
            case 'matrix-rain': this.drawMatrixRain(ctx, config, progress, width, height); break;
            case 'cyber-grid': this.drawCyberGrid(ctx, config, progress, width, height); break;
            case 'neural-net': this.drawNeuralNet(ctx, config, progress, width, height); break;
            case 'cosmic-drift': this.drawCosmicDrift(ctx, config, progress, width, height); break;
            case 'geometric-void': this.drawGeometricVoid(ctx, config, progress, width, height); break;
            default: this.drawNeonPulse(ctx, config, progress, width, height);
        }
    }

    private static drawCinematicImage(
        ctx: CanvasRenderingContext2D, 
        img: HTMLImageElement, 
        progress: number, 
        width: number, 
        height: number,
        text?: string
    ) {
        // Ken Burns Effect (Zoom In & Pan)
        const scale = 1 + (progress * 0.15); // Zoom in 15%
        const xOffset = (width * 0.05) * Math.sin(progress * Math.PI / 2); // Slight pan right

        ctx.save();
        ctx.translate(width/2, height/2);
        ctx.scale(scale, scale);
        ctx.translate(-width/2 - xOffset, -height/2);

        // Draw Image Covering Canvas (Object-Fit: Cover logic)
        const imgRatio = img.width / img.height;
        const canvasRatio = width / height;
        let renderW, renderH, renderX, renderY;

        if (imgRatio > canvasRatio) {
            renderH = height;
            renderW = height * imgRatio;
            renderX = (width - renderW) / 2;
            renderY = 0;
        } else {
            renderW = width;
            renderH = width / imgRatio;
            renderX = 0;
            renderY = (height - renderH) / 2;
        }

        ctx.drawImage(img, renderX, renderY, renderW, renderH);
        ctx.restore();

        // Cinematic Overlays
        // 1. Vignette
        const gradient = ctx.createRadialGradient(width/2, height/2, width*0.3, width/2, height/2, width*0.8);
        gradient.addColorStop(0, "rgba(0,0,0,0)");
        gradient.addColorStop(1, "rgba(0,0,0,0.6)");
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, width, height);

        // 2. Letterbox (Cinematic Bars) if requested or for style
        const barHeight = height * 0.1;
        ctx.fillStyle = "black";
        ctx.fillRect(0, 0, width, barHeight * (1-progress*0.1)); // Bars slowly recede or stay static
        ctx.fillRect(0, height - (barHeight * (1-progress*0.1)), width, barHeight);

        // 3. Text Overlay
        if (text) {
            ctx.save();
            ctx.shadowColor = "rgba(0,0,0,0.8)";
            ctx.shadowBlur = 20;
            ctx.fillStyle = "rgba(255, 255, 255, 0.9)";
            ctx.font = `300 ${width * 0.06}px 'Poppins', sans-serif`;
            ctx.textAlign = "center";
            ctx.textBaseline = "bottom";

            // Fade in text
            ctx.globalAlpha = Math.min(1, progress * 2); 

            // Wrap text
            const words = text.split(' ');
            let line = '';
            let y = height - (barHeight * 1.5);
            for(let n = 0; n < words.length; n++) {
                const testLine = line + words[n] + ' ';
                const metrics = ctx.measureText(testLine);
                const testWidth = metrics.width;
                if (testWidth > width * 0.8 && n > 0) {
                    ctx.fillText(line, width/2, y);
                    line = words[n] + ' ';
                    y += (width * 0.07);
                } else {
                    line = testLine;
                }
            }
            ctx.fillText(line, width/2, y);
            ctx.restore();
        }
    }

    // ... (Keep existing procedural render methods: drawNeonPulse, drawKineticSlide, etc. unchanged)
    private static drawNeonPulse(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { text, accentColor } = config;
        const scale = 1 + Math.sin(progress * Math.PI * 4) * 0.05;
        ctx.save();
        ctx.translate(width / 2, height / 2);
        ctx.scale(scale, scale);
        ctx.shadowBlur = 40 + Math.sin(progress * Math.PI * 4) * 20;
        ctx.shadowColor = accentColor;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`; 
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        const words = text.split(' ');
        if (text.length > 20) {
             const mid = Math.floor(words.length / 2);
             const line1 = words.slice(0, mid).join(' ');
             const line2 = words.slice(mid).join(' ');
             ctx.fillText(line1, 0, -width * 0.05);
             ctx.fillText(line2, 0, width * 0.05);
        } else {
             ctx.fillText(text, 0, 0);
        }
        ctx.strokeStyle = accentColor;
        ctx.lineWidth = width * 0.01;
        ctx.beginPath();
        ctx.arc(0, 0, (width * 0.4) + Math.sin(progress * Math.PI * 2) * 20, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
    }

    private static drawKineticSlide(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { text, accentColor } = config;
        ctx.save();
        ctx.translate(width / 2, height / 2);
        ctx.rotate(-Math.PI / 6); 
        ctx.fillStyle = accentColor;
        ctx.font = `bold ${width * 0.15}px Inter, sans-serif`;
        ctx.textAlign = "center";
        const slideSpeed = 1000;
        for(let i = -6; i <= 6; i++) {
            const dir = i % 2 === 0 ? 1 : -1;
            const xPos = (dir * (progress * slideSpeed) + (i * 50)) % (width + 1000) - (width/2 + 500);
            ctx.globalAlpha = 1 - (Math.abs(i) * 0.12);
            if(ctx.globalAlpha < 0) ctx.globalAlpha = 0;
            ctx.fillText(text.toUpperCase(), xPos, i * (width * 0.14));
        }
        ctx.restore();
    }

    private static drawMatrixRain(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        ctx.fillStyle = config.accentColor;
        ctx.font = `${width * 0.03}px monospace`;
        const columns = Math.floor(width / (width * 0.03));
        for (let i = 0; i < columns; i++) {
            const speed = (Math.sin(i * 99) + 2) * 2000; 
            const offset = Math.cos(i * 50) * height;
            const y = (offset + progress * speed) % height;
            for (let j = 0; j < 5; j++) {
                 const char = String.fromCharCode(0x30A0 + Math.abs(Math.floor(Math.sin(i * j + progress) * 96)));
                 ctx.globalAlpha = 1 - (j * 0.2);
                 ctx.fillText(char, i * (width * 0.03), y - j * (width * 0.03));
            }
        }
        ctx.save();
        ctx.globalAlpha = 1;
        ctx.shadowColor = "#000000";
        ctx.shadowBlur = 20;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text, width/2, height/2);
        ctx.restore();
    }

    private static drawCyberGrid(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor } = config;
        const horizon = height * 0.4;
        ctx.save();
        const sunY = horizon - (height * 0.1);
        const sunGradient = ctx.createLinearGradient(0, sunY - 100, 0, sunY + 100);
        sunGradient.addColorStop(0, "#F59E0B"); 
        sunGradient.addColorStop(1, "#EC4899"); 
        ctx.fillStyle = sunGradient;
        ctx.beginPath();
        ctx.arc(width/2, sunY, width * 0.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.rect(0, horizon, width, height - horizon);
        ctx.clip();
        const gridGrad = ctx.createLinearGradient(0, horizon, 0, height);
        gridGrad.addColorStop(0, "rgba(0,0,0,1)");
        gridGrad.addColorStop(1, config.accentColor);
        ctx.fillStyle = gridGrad;
        ctx.fillRect(0, horizon, width, height - horizon);
        ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
        ctx.lineWidth = 2;
        const perspectiveCenter = width / 2;
        for(let i = -10; i <= 10; i++) {
            const x = perspectiveCenter + (i * width * 0.2) * (1 + Math.sin(progress * 0.1));
            ctx.beginPath();
            ctx.moveTo(perspectiveCenter, horizon);
            ctx.lineTo(x + (i * width * 1.5), height);
            ctx.stroke();
        }
        const speed = 2000;
        const loopPos = (progress * speed) % 200;
        for (let i = 0; i < 20; i++) {
            const y = horizon + Math.pow(i, 2.5) * 2 + loopPos; 
            if (y > height) continue;
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(width, y);
            ctx.stroke();
        }
        ctx.restore();
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = 30;
        ctx.fillStyle = "#ffffff";
        ctx.font = `italic bold ${width * 0.1}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text.toUpperCase(), width/2, height * 0.3);
    }

    private static drawNeuralNet(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor } = config;
        const particleCount = 40;
        const particles = [];
        for(let i=0; i<particleCount; i++) {
            const x = ((i * 137.5) % width);
            const y = ((i * 293.3 + progress * 500) % height);
            particles.push({x, y});
        }
        ctx.fillStyle = accentColor;
        ctx.strokeStyle = accentColor;
        ctx.lineWidth = 1;
        for(let i=0; i<particleCount; i++) {
            const p1 = particles[i];
            ctx.beginPath();
            ctx.arc(p1.x, p1.y, 4, 0, Math.PI * 2);
            ctx.fill();
            for(let j=i+1; j<particleCount; j++) {
                const p2 = particles[j];
                const dist = Math.hypot(p1.x - p2.x, p1.y - p2.y);
                if (dist < width * 0.15) {
                    ctx.globalAlpha = 1 - (dist / (width * 0.15));
                    ctx.beginPath();
                    ctx.moveTo(p1.x, p1.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.stroke();
                }
            }
        }
        ctx.globalAlpha = 1;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text, width/2, height/2);
    }

    private static drawCosmicDrift(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor } = config;

        const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, width);
        grad.addColorStop(0, "#1e1b4b"); 
        grad.addColorStop(1, "#000000");
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, width, height);

        ctx.fillStyle = "#ffffff";
        const starCount = 100;
        for (let i = 0; i < starCount; i++) {
            const r = (i * 123.45) % width;
            const angle = (i * 32.1 + progress * Math.PI) % (Math.PI * 2);
            const dist = (i * 10 + progress * 1000) % (Math.max(width, height) / 1.5);

            const x = width/2 + Math.cos(angle + i) * dist;
            const y = height/2 + Math.sin(angle + i) * dist;

            const size = (dist / width) * 4;
            ctx.globalAlpha = Math.min(1, dist / (width/4));

            ctx.beginPath();
            ctx.arc(x, y, size, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.globalAlpha = 0.3;
        ctx.fillStyle = accentColor;
        const cloudX = width/2 + Math.sin(progress * Math.PI) * 200;
        const cloudY = height/2 + Math.cos(progress * Math.PI) * 200;
        ctx.filter = "blur(100px)"; 
        ctx.beginPath();
        ctx.arc(cloudX, cloudY, width/3, 0, Math.PI * 2);
        ctx.fill();
        ctx.filter = "none";

        ctx.globalAlpha = 1;
        ctx.save();
        ctx.translate(width/2, height/2);
        const textScale = 1 + Math.sin(progress * Math.PI * 2) * 0.1;
        ctx.scale(textScale, textScale);
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = 50;
        ctx.fillStyle = "#ffffff";
        ctx.font = `900 ${width * 0.1}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(config.text.toUpperCase(), 0, 0);
        ctx.restore();
    }

    private static drawGeometricVoid(ctx: CanvasRenderingContext2D, config: VideoConfig, progress: number, width: number, height: number) {
        const { accentColor, backgroundColor } = config;

        ctx.fillStyle = backgroundColor;
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = accentColor;
        ctx.lineWidth = 3;
        const centerX = width / 2;
        const centerY = height / 2;
        const shapeCount = 10;
        const maxRadius = width * 0.8;

        for (let i = 0; i < shapeCount; i++) {
            const p = (progress + i/shapeCount) % 1;
            const size = p * maxRadius;
            const rotation = p * Math.PI * 2;
            const opacity = 1 - p;

            ctx.save();
            ctx.translate(centerX, centerY);
            ctx.rotate(rotation);
            ctx.globalAlpha = opacity;

            ctx.beginPath();
            for (let j = 0; j < 6; j++) {
                const angle = (j * Math.PI * 2) / 6;
                const x = Math.cos(angle) * size;
                const y = Math.sin(angle) * size;
                if (j === 0) ctx.moveTo(x, y);
                else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();
            ctx.restore();
        }

        ctx.globalAlpha = 1;
        ctx.fillStyle = "#ffffff";
        ctx.font = `bold ${width * 0.08}px Inter, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = 20;
        ctx.fillText(config.text, centerX, centerY);
    }

    public async generate(config: VideoConfig): Promise<Blob> {
        // Set dimensions based on aspect ratio
        if (config.aspectRatio === '16:9') {
            this.canvas.width = 1920;
            this.canvas.height = 1080;
        } else if (config.aspectRatio === '1:1') {
            this.canvas.width = 1080;
            this.canvas.height = 1080;
        } else {
            this.canvas.width = 1080;
            this.canvas.height = 1920;
        }

        this.ctx = this.canvas.getContext('2d')!;

        // Handle Image loading for AI mode
        let imageElement: HTMLImageElement | undefined;
        if (config.mode === 'ai-generative' && config.referenceImage) {
            imageElement = new Image();
            imageElement.src = config.referenceImage;
            await new Promise((resolve) => { imageElement!.onload = resolve; });
        }

        // Initialize Audio
        const audioGenerator = new AudioGenerator();
        audioGenerator.generateSoundtrack(config.audioPrompt || 'Epic Score', config.duration);
        const audioStream = audioGenerator.getStream();

        // Canvas Stream
        const canvasStream = this.canvas.captureStream(config.fps);

        // Combine streams
        const combinedStream = new MediaStream([
            ...canvasStream.getVideoTracks(),
            ...audioStream.getAudioTracks()
        ]);

        const recorder = new MediaRecorder(combinedStream, {
            mimeType: 'video/webm;codecs=vp9,opus'
        });

        const chunks: BlobPart[] = [];
        recorder.ondataavailable = (e) => {
            if (e.data.size > 0) chunks.push(e.data);
        };

        return new Promise((resolve, reject) => {
            recorder.onstop = () => {
                const blob = new Blob(chunks, { type: 'video/webm' });
                audioGenerator.close();
                resolve(blob);
            };

            recorder.onerror = (e) => reject(e);

            recorder.start();

            let currentFrame = 0;
            const totalFrames = config.duration * config.fps;

            const renderLoop = () => {
                if (currentFrame >= totalFrames) {
                    recorder.stop();
                    return;
                }

                const progress = currentFrame / totalFrames;

                VideoRenderer.drawFrame(
                    this.ctx, 
                    config, 
                    progress, 
                    this.canvas.width, 
                    this.canvas.height, 
                    imageElement
                );

                currentFrame++;
                setTimeout(renderLoop, 1000 / config.fps); 
            };

            renderLoop();
        });
    }
}

import { VideoConfig, VideoGenerationResponse } from './types';
import { VideoRenderer } from './VideoRenderer';

/**
 * Routes the generation request. Both modes now run LOCALLY via the Canvas Renderer.
 */
export async function postCustomVideo(config: VideoConfig): Promise<VideoGenerationResponse> {
    // Both modes use the same local renderer now, just different draw logic internally.
    return generateLocalVideo(config);
}

async function generateLocalVideo(config: VideoConfig): Promise<VideoGenerationResponse> {
    try {
        const renderer = new VideoRenderer();
        const videoBlob = await renderer.generate({
            ...config,
            style: config.style || 'neon-pulse',
            backgroundColor: config.backgroundColor || '#000000',
            accentColor: config.accentColor || '#00E5FF',
            fps: config.fps || 30
        });
        const videoUrl = URL.createObjectURL(videoBlob);

        const engineName = config.mode === 'ai-generative' 
            ? 'Nova Cinematic Engine (Native)' 
            : 'Nova Canvas Engine v2.1';

        return {
            success: true,
            videoUrl: videoUrl,
            metadata: {
                duration: config.duration,
                size: videoBlob.size,
                format: 'video/webm',
                engine: engineName
            }
        };
    } catch (error: any) {
        console.error("Video Gen Error:", error);
        return {
            success: false,
            error: error.message || "Unknown error during video generation"
        };
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { VideoConfig, AnimationStyle, AspectRatio, GenerationMode } from '../nova/custom_video_model/types';
import { postCustomVideo } from '../nova/custom_video_model/api';
import { VideoRenderer } from '../nova/custom_video_model/VideoRenderer';
import { XCircleIcon, SparklesIcon, PlayIcon, VideoIcon, CodeBracketIcon, PhotoIcon, CheckBadgeIcon, ArrowUpTrayIcon, PaperClipIcon, VideoCameraIcon, TrashIcon, SpeakerWaveIcon } from './icons';
import { LoadingSpinner } from './LoadingSpinner';
import { motion, AnimatePresence } from 'framer-motion';
// No external GenAI import needed for UI logic now

interface CustomVideoModalProps {
    onClose: () => void;
    onSuccess: (videoUrl: string, text: string) => void;
}

const CustomVideoModal: React.FC<CustomVideoModalProps> = ({ onClose, onSuccess }) => {
    // --- Global State ---
    const [mode, setMode] = useState<GenerationMode>('procedural'); // 'procedural' or 'ai-generative'
    const [text, setText] = useState('');
    const [aspectRatio, setAspectRatio] = useState<AspectRatio>('16:9');
    const [generating, setGenerating] = useState(false);
    const [progress, setProgress] = useState(0);
    const [resultVideoUrl, setResultVideoUrl] = useState<string | null>(null);
    const [generationError, setGenerationError] = useState<string | null>(null);

    // --- Procedural Mode State ---
    const [style, setStyle] = useState<AnimationStyle>('cosmic-drift');
    const [duration, setDuration] = useState(5);
    const [backgroundColor, setBackgroundColor] = useState('#0a0a0a');
    const [accentColor, setAccentColor] = useState('#6366f1');
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const requestRef = useRef<number>(0);
    const startTimeRef = useRef<number>(0);

    // --- AI Mode State ---
    const [referenceImage, setReferenceImage] = useState<string | null>(null);
    const [visualStyle, setVisualStyle] = useState('Cinematic (Default)');
    const [audioMood, setAudioMood] = useState('Epic Score');
    const fileInputRef = useRef<HTMLInputElement>(null);

    const visualStyles = ['Cinematic (Default)', 'Film Noir', 'Vibrant', 'Soft Focus'];
    const audioMoods = ['Epic Score', 'Cinematic Ambience', 'Cyberpunk Synth', 'Nature Sounds', 'Silent'];

    // --- Live Preview Loop (Procedural Only) ---
    useEffect(() => {
        if (mode !== 'procedural') {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
            return;
        }

        const animate = (time: number) => {
            if (startTimeRef.current === 0) startTimeRef.current = time;
            const elapsed = time - startTimeRef.current;
            const loopDuration = duration * 1000;
            const progress = (elapsed % loopDuration) / loopDuration;

            if (canvasRef.current) {
                const ctx = canvasRef.current.getContext('2d');
                if (ctx) {
                    const width = canvasRef.current.width;
                    const height = canvasRef.current.height;
                    const config: VideoConfig = {
                        text: text || "Nova AI",
                        style,
                        duration,
                        backgroundColor,
                        accentColor,
                        fps: 30,
                        aspectRatio,
                        mode: 'procedural'
                    };
                    VideoRenderer.drawFrame(ctx, config, progress, width, height);
                }
            }
            requestRef.current = requestAnimationFrame(animate);
        };
        requestRef.current = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(requestRef.current!);
    }, [text, style, duration, backgroundColor, accentColor, aspectRatio, mode]);

    // --- Handlers ---

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setReferenceImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const handleGenerate = async () => {
        if (!text && !referenceImage) return;
        setGenerationError(null);
        setGenerating(true);
        setResultVideoUrl(null);

        let progressVal = 0;
        // Faster progress since it's local
        const progressInterval = setInterval(() => {
            progressVal = Math.min(progressVal + 2, 95);
            setProgress(progressVal);
        }, 100);

        try {
            const config: VideoConfig = {
                mode,
                text,
                style,
                duration,
                backgroundColor,
                accentColor,
                fps: 30,
                aspectRatio,
                referenceImage: referenceImage || undefined,
                visualStyle: mode === 'ai-generative' ? visualStyle : undefined,
                audioPrompt: mode === 'ai-generative' ? audioMood : undefined
            };

            const response = await postCustomVideo(config);

            clearInterval(progressInterval);
            setProgress(100);

            if (response.success && response.videoUrl) {
                setResultVideoUrl(response.videoUrl);
            } else {
                setGenerationError(response.error || "Generation failed.");
            }
        } catch (e: any) {
            clearInterval(progressInterval);
            setGenerationError(e.message || "An unexpected error occurred.");
        } finally {
            setGenerating(false);
        }
    };

    const handleSaveAndClose = () => {
